window.__HOT_STORIES__ = {"schemaVersion":1,"updatedAt":"2026-11-15T22:56:31.496Z","stories":{"d01448e7-e6ef-4224-9e13-5f4b350dd6ed":{"publicId":"d01448e7-e6ef-4224-9e13-5f4b350dd6ed","title":"黄仁勋辞任英伟达CEO，CFO克雷斯临时接任","status":"active","sourceCount":25,"reportCount":70,"firstReportAt":"2026-10-29T13:42:38.000Z","latestAt":"2026-11-15T13:00:00.000Z","latest":"黄仁勋因婚外情风波辞任 Nvidia CEO","digest":"英伟达董事会11月12日宣布，联合创始人、总裁兼CEO黄仁勋即刻辞去CEO及董事职务，结束33年执掌；自2013年起任CFO的Colette Kress出任临时CEO，前Synopsys CEO Harvey Jones任公司首位董事长，董事会已启动内外部继任者遴选。\n\n辞职前，黄仁勋已向员工承认与英伟达客户Megaspeed高管Alice Huang的婚外情，美国情报界认为后者涉外国情报活动；《纽约时报》随后报道他与一名直接下属存在第二段婚外情。董事会启动独立调查时称无理由认为公司机密受损，但《华尔街日报》报道董事会接近决定罢免他，最终以辞职告终。\n\n消息公布后英伟达股价大跌，市值跌破4万亿美元；国会中国特设委员会主席Moolenaar要求新领导层把国家安全置于首位。黄仁勋原定的ElevenLabs Summit等演讲已取消。","digestUpdatedAt":"2026-11-15T19:05:51.071Z","reports":[{"id":"qcyfp81twlwsaayzpdun87hcp","title":"英伟达黄仁勋卸任、阿里芯片子公司赴港IPO、Qwen4-Max 首次亮相","summary":"英伟达宣布黄仁勋于11月11日卸任CEO及董事，CFO Colette Kress 出任临时CEO，董事会已就涉及其与英伟达中国业务的相关指控启动独立调查。阿里11月10日披露，芯片子公司 T-Head 已于9月11日以保密方式提交香港上市申请，发行条款尚未确定。阿里11月11日预览下一代 Qwen4 家族首款模型 Qwen4-Max，支持文本、图像、视频输入和100万 token 上下文窗口。","sourceName":"Recode China AI（RSS）","firstParty":false,"publishedAt":"2026-11-15T13:06:31.000Z","url":"https://www.recodechinaai.com/p/nvidia-without-jensen-alibabas-chip"},{"id":"uuvl4lt0co7rt17sye7475r7z","title":"黄仁勋因婚外情风波辞任 Nvidia CEO","summary":"The Verge 周刊栏目梳理黄仁勋辞任 Nvidia CEO 事件：纽约时报 10 月 29 日报道他与 Megaspeed 高管 Alice Huang 关系密切。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-15T13:00:00.000Z","url":"https://www.theverge.com/column/1033943/jensen-huang-nvidia-china-spying-scandal-resignation"},{"id":"wum2o1ou49rhookuv10ck6ow6","title":"X.PIN 转发 WSJ 关于黄仁勋辞任 Nvidia 的社论并附新加坡政府澄清声明","summary":"X.PIN 引用 WSJ 社论，称黄仁勋辞任 Nvidia 虽有必要但对公司和美国 AI 产业造成遗憾损害，并猜测这或许是中国的计划。所附图片为新加坡政府 2026 年 10 月 31 日的澄清声明，针对 WSJ 10 月 30 日关于 Alice Huang 涉嫌向中国传递信息、与黄仁勋关系密切的报道，声明新加坡政府及其官员从未表达相关担忧，也从未就 Alice Huang 展开此类调查，并附上了与 WSJ 的往来问答。","sourceName":"X：X.PIN (@thexpin)","firstParty":false,"publishedAt":"2026-11-14T14:49:22.000Z","url":"https://x.com/thexpin/status/2121616487249219804"},{"id":"p1mfh9oe0xbq4evyru5pp1ikt","title":"Nvidia 危机与 Anthropic IPO 前夜的 Cerebral Valley AI Summit 现场观察","summary":"Newcomer 在旧金山 Cerebral Valley AI Summit 现场报道：Jensen Huang 因第二段婚外情披露辞职，Reuters 当天报道存在第三段，与会者多认为 Nvidia 短期无碍但生态承压，Databricks CEO 称其对整个生态是打击。","sourceName":"Newcomer 新闻长文（RSS）","firstParty":false,"publishedAt":"2026-11-13T19:27:39.000Z","url":"https://www.newcomer.co/p/nvidia-crises-anthropic-ipo-and-off"},{"id":"cs8aaqi9s05ph4pos2vguvohq","title":"Ed Zitron 长文解析 NVIDIA GPU 走私指控与历史争议","summary":"Ed Zitron 在付费长文中分析围绕 NVIDIA 的 GPU 走私指控网络，并引用 Culper Research 2026 年 5 月报告称相关出货可能占其 2026 财年营收超 20%（逾 430 亿美元）。文章还回顾了 NVIDIA 过往与 SEC 的处罚记录及产品评测争议。","sourceName":"Ed Zitron 长文 / Where’s Your Ed At（RSS）","firstParty":false,"publishedAt":"2026-11-13T18:19:39.000Z","url":"https://www.wheresyoured.at/hg-megaspeed/"},{"id":"il5gmcwg4dn1n3sj5vl2bsuij","title":"英伟达CEO黄仁勋辞任，CFO临时接任，美国国会就芯片销售展开调查","summary":"英伟达联合创始人黄仁勋辞去CEO一职，CFO Colette Kress出任临时CEO。美国国会就英伟达芯片对华销售及相关事宜展开调查，并要求黄仁勋作证。报道提及Megaspeed公司两年内采购价值48亿美元的英伟达芯片，美国与新加坡曾就芯片出口合规问题对该企业进行调查。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-13T15:58:00.000Z","url":"https://techcrunch.com/2026/11/13/nvidia-ceo-jensen-huangs-affair-with-alleged-chinese-spy-a-timeline/"},{"id":"wkxqhc700pv5zgpew0cj5zyec","title":"Vergecast 播客解读黄仁勋辞任 NVIDIA CEO 后的连锁影响","summary":"The Vergecast 播客中 David Pierce 与 Nilay 梳理 NVIDIA CEO 黄仁勋周四辞职事件，并讨论后续可能展开的更大故事：NVIDIA 在中国的业务、美国政府的态度，以及整个 AI 行业的稳定性。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-13T14:47:16.000Z","url":"https://www.theverge.com/podcast/1032866/jensen-huang-nvidia-china-trump-vergecast"},{"id":"se0y4v3gihr6s0jmrc5vuv1zo","title":"AINews：黄仁勋辞任 NVIDIA CEO，Colette Kress 出任临时 CEO","summary":"Latent Space 的 AI 新闻日报头条是 NVIDIA 宣布黄仁勋在任职 33 年后辞去 CEO、总裁和董事职务，CFO Colette Kress 出任临时 CEO，SEC 文件显示董事会于 11 月 11 日接受辞呈，此前董事会已就 NYT 报道的绯闻事件展开独立调查。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-13T09:04:13.000Z","url":"https://latent.space/p/ainews-jensen-huang-resigns-after-33-years-leading-nvidia/"},{"id":"c38th8p4klxei4v40fxntey09","title":"黄仁勋辞任英伟达CEO全时间线复盘：两桩风波、接班人与33年生涯","summary":"11月12日英伟达公告黄仁勋辞去总裁、CEO和董事职务，即刻生效，未提原因；股价当日跌13%，市值回落至4万亿美元以下，CFO科莱特·克雷斯临时接任，哈维·琼斯成为公司33年来首位董事长。","sourceName":"X：卡尔的 AI 沃茨 (@aiwarts)","firstParty":false,"publishedAt":"2026-11-13T04:17:46.000Z","url":"https://x.com/aiwarts/status/2121095150114140317"},{"id":"sntaq2q8jo5gkp6hpgn0wy7g6","title":"Rohan Paul 日报：黄仁勋结束 33 年任期辞任 Nvidia CEO，Colette Kress 任临时 CEO","summary":"Rohan Paul 发布日报称，黄仁勋辞任 Nvidia CEO，结束 33 年任期，CFO Colette Kress 出任临时 CEO。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-13T02:05:59.000Z","url":"https://x.com/rohanpaul_ai/status/2121061984896708744"},{"id":"yb6o3s9lyxkb8xf7ykhrj3cr1","title":"黄仁勋辞任 Nvidia CEO，Casey Newton 撰文评析硅谷创始人崇拜的终结","summary":"Nvidia 于周四宣布 CEO 黄仁勋辞职，CFO Colette Kress 暂代 CEO，此前纽约时报曝光其第二段婚外情，路透社随后披露第三段。作者 Casey Newton 评析其职业生涯，指出硅谷创始人崇拜带来的两大问题，包括富豪寡头化和 key-man 风险，并称黄仁勋没有继任计划。","sourceName":"Platformer（热点 RSS）","firstParty":false,"publishedAt":"2026-11-13T01:43:23.000Z","url":"https://www.platformer.news/jensen-huang-resigns-founder-cult-accountability/"},{"id":"y51nb19h2bj96to0swwkv57oy","title":"黄仁勋辞任英伟达CEO：14天时间线与33年生涯回顾","summary":"11月12日英伟达公告黄仁勋辞去总裁、CEO和董事职务，即刻生效，股价当日跌13%，市值跌回4万亿美元以下，CFO科莱特·克雷斯临时接任。作者梳理了英伟达三份公告、员工信和SEC文件等一手材料，回顾了黄仁勋33年的职业生涯及公司治理层面的变化。","sourceName":"公众号：卡尔的AI沃茨","firstParty":false,"publishedAt":"2026-11-13T01:03:00.000Z","url":"https://mp.weixin.qq.com/s/RB5f6wfZgI46D8ux_vK5LA"},{"id":"uef3cjv8f2j9x82ncz5frcfjg","title":"黄仁勋辞去英伟达总裁与CEO职务，卡兹克梳理事件始末","summary":"作者梳理黄仁勋辞去英伟达总裁、首席执行官和董事职务的来龙去脉，从2022年美国对A100、H100等芯片禁售写起，串起Megaspeed、黄乐与黄仁勋的关联、75亿美元芯片交易指控、《纽约时报》与The Information的系列调查报道，到11月12日晚公告辞职的14天时间线，并附带股价开盘下跌14个点等反应。","sourceName":"X：卡兹克 (@Khazix0918)","firstParty":false,"publishedAt":"2026-11-13T00:29:40.000Z","url":"https://x.com/Khazix0918/status/2121037747259625601"},{"id":"hqidckwtzcu63rwc19czidjld","title":"黄仁勋辞去英伟达 CEO，Hugging Face CEO 德朗格表态继续力挺开源 AI","summary":"黄仁勋于 11 月 12 日辞去英伟达总裁、CEO 及董事职务，即刻生效，CFO 科莱特·克雷斯出任临时 CEO，公司启动新 CEO 遴选。Hugging Face CEO 德朗格在领英称这是令人难过的一天，表示将比以往更努力捍卫开源人工智能。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-12T23:56:58.007Z","url":"https://www.ithome.com/1/026/469.htm"},{"id":"t86m3q7vdlqmvm2zmx91vps5a","title":"黄仁勋辞去英伟达总裁兼CEO，作者梳理14天风波始末","summary":"英伟达公告黄仁勋辞去总裁、CEO和董事职务，即刻生效，股价开盘下跌14个点。作者依据《纽约时报》、The Information 等报道梳理脉络：从2022年A100、H100对华禁售，到 Megaspeed 采购争议、黄乐被指涉情报活动，再到婚外情曝光后董事会于10月29日起14天内收网，黄仁勋在英伟达33年的时代就此结束。","sourceName":"公众号：数字生命卡兹克","firstParty":false,"publishedAt":"2026-11-12T23:56:00.000Z","url":"https://mp.weixin.qq.com/s/ToplAo9NHP356Fu-hbYlsg"},{"id":"ey8wwzav6ohoxh11jw491kcjg","title":"黄仁勋辞职引发对 Nvidia 开源 AI 战略延续性的疑问","summary":"Nvidia CEO 黄仁勋周四因婚外情风波辞职，引发对其开源 AI 支持路线能否延续的疑问。他此前推动 Nemotron 开源模型、支持收购 Hugging Face 的 130 亿美元交易，并牵头的 25 家公司联名信反对政府过度限制开源权重模型；CFO Colette Kress 已出任临时 CEO。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T18:39:23.000Z","url":"https://techcrunch.com/2026/11/12/jensen-huangs-exit-puts-nvidias-support-for-open-source-in-question/"},{"id":"n73ab4h9gqlu6ucv69ynzxln4","title":"SemiAnalysis 分析黄仁勋辞任 Nvidia 后的公司结构与出口管制走向","summary":"SemiAnalysis 长文分析黄仁勋辞任 Nvidia CEO 后的连锁影响，作者推测其去职与 GPU 走私及美国推动 RASA 出口管制立法有关。文中指出公司约 60 名直管高管的扁平结构依赖黄本人，继任者 Colette Kress 为临时 CEO，Ian Buck 与 Jonah Alben 被视为技术侧人选但无人能全面接替。","sourceName":"SemiAnalysis 长文 RSS（RSS）","firstParty":false,"publishedAt":"2026-11-12T18:06:26.000Z","url":"https://newsletter.semianalysis.com/p/nvidia-and-the-world-without-jensen"},{"id":"licdk6vosezxouovor3gvtcpe","title":"The Verge 分析黄仁勋辞职与 Nvidia 芯片走私疑云","summary":"The Verge 作者 Elizabeth Lopatto 分析 Nvidia 宣布黄仁勋辞职一事，认为第二桩婚外情只是导火索，真正原因或与芯片走私指控有关。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T17:44:33.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1032069/jensen-huang-resignation-affair-chips-smuggling"},{"id":"rda6uss1k4k96ygzfl7a3byk0","title":"美众议院中国特设委员会主席 Moolenaar 就黄仁勋辞任 NVIDIA 发表声明","summary":"美众议院中国特设委员会主席 Rep. John Moolenaar 就黄仁勋辞任 NVIDIA 发表声明，称其被解职是一个本可避免的不幸结局。他表示 NVIDIA 现在必须改变公司治理方式，任命把国家安全置于最优先的领导层，并称国会应尽快在年底国防授权法案中通过两党出口管制立法。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-12T17:27:52.000Z","url":"https://x.com/rohanpaul_ai/status/2120931596396335208"},{"id":"sowwn4rv7ggtd41l0d469f1id","title":"Jensen Huang 被 Nvidia 董事会罢免 CEO 后，可能冲击 AI 行业的五个方面","summary":"Nvidia 董事会于周四罢免 CEO Jensen Huang，起因是他承认婚外情，且其中一名对象被美国政府怀疑涉外国情报活动、并任职于涉嫌转运受限 Nvidia 芯片的新加坡 neocloud。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T16:32:33.000Z","url":"https://techcrunch.com/2026/11/12/five-ways-jensen-huangs-ouster-from-nvidia-could-damage-the-ai-industry/"},{"id":"toq4wymx9maq8lhhz8jryi0sv","title":"黄仁勋辞任 Nvidia CEO，Azeem Azhar 分析其对 AI 热潮的影响","summary":"作者 Azeem Azhar 分析黄仁勋辞任 Nvidia CEO 一事：公司在未设接班政策的情况下由 CFO Colette Kress 临时接手。文章指出 Nvidia 五年间售出近 1400 万颗旗舰 AI 芯片、占 85% 市场，过去一年在欧洲投资近 100 亿美元，而黄仁勋本人是公司与 AI 生态的关键纽带。","sourceName":"Azeem Azhar：Exponential View（RSS）","firstParty":false,"publishedAt":"2026-11-12T16:19:28.000Z","url":"https://www.exponentialview.co/p/jensen-huang-and-the-future-of-the"},{"id":"jferw1o1blgp1kv5z4no8qb5s","title":"NVIDIA CEO 黄仁勋辞职，CFO Colette Kress 出任临时 CEO","summary":"NVIDIA 联合创始人黄仁勋于当天早晨辞去 CEO 和董事职务，此前董事会就其与直属下属的婚外情及相关情报指控展开调查。董事会任命任职超过 13 年的 CFO Colette Kress 为临时 CEO，Harvey Jones 出任首任董事会主席并致信员工；Kress 在首封临时 CEO 信中称这是一段极其艰难的时期，公司将于 11 月 18 日 9am PT 举行全员会议。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T15:48:12.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1032028/read-nvidias-internal-emails-jensen-huang"},{"id":"l7dv9twcz25784wh4ttbhxm78","title":"Nvidia CEO 黄仁勋辞职，CFO Colette Kress 出任临时 CEO","summary":"Nvidia 董事会宣布，执掌公司 33 年的联合创始人兼 CEO 黄仁勋辞去总裁、CEO 及董事职务，即刻生效。辞职发生在媒体报道他的两段婚外情之后，其中一名对象被指涉情报活动，另一名是其直接下属；公司此前从未设立继任计划。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T15:37:29.000Z","url":"https://techcrunch.com/2026/11/12/jensen-huang-is-out-at-nvidia-who-is-colette-kress-his-interim-replacement/"},{"id":"xe5jgbho8qhh6ahx1353wdycv","title":"NVIDIA 官宣 CEO 过渡，发布声明链接","summary":"NVIDIA Newsroom 宣布 CEO 过渡，附官方新闻稿链接 https://nvidianews.nvidia.com/news/nvidia-announces-ceo-transition。转发者 X.PIN 仅以“Such an era!”感叹，未补充细节。","sourceName":"X：X.PIN (@thexpin)","firstParty":false,"publishedAt":"2026-11-12T14:59:46.000Z","url":"https://x.com/thexpin/status/2120894325370577402"},{"id":"aol3stj5rjrl9sq35s3d4fzt6","title":"《大西洋月刊》谈黄仁勋在华盛顿的影响力","summary":"《大西洋月刊》有篇有意思的文章。\n\n这期节目展示了黄仁勋的影响力在华盛顿扩散得有多广。\n\n据文章称，在报道公开前数月，警告就已传达至政府高层官员。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-12T14:53:11.000Z","url":"https://x.com/rohanpaul_ai/status/2120892671178973263"},{"id":"cq52ebt0mx19monojyqyuxdo1","title":"黄仁勋辞任 Nvidia CEO，CFO Colette Kress 接任临时负责人","summary":"Gary Marcus 称黄仁勋已辞去 Nvidia CEO 职务，董事会推动其离任，由 CFO Colette Kress 出任临时负责人。他表示消息公布后 Nvidia 股价跌幅从盘前 8% 扩大到开盘时的 13%，并担心黄仁勋主导的循环融资可能崩塌，以及此前承诺投入 Anthropic 的数十亿美元 IPO 资金是否兑现成为焦点。他同时列举了国会调查、中国市场影响和政治层面的后续不确定性。","sourceName":"Gary Marcus：The Road to AI We Can Trust（RSS）","firstParty":false,"publishedAt":"2026-11-12T14:44:04.000Z","url":"https://garymarcus.substack.com/p/jensen-huang-resigns"},{"id":"m76r4bnrvb21vkm8wn2khk0jr","title":"Kate Clark 转发 WSJ 报道称 Nvidia 正准备罢免 CEO 黄仁勋并征集信源","summary":"记者 Kate Clark 分享 WSJ 报道链接，该报道称 Nvidia 正准备罢免 CEO 黄仁勋。她同时留下 Signal 联系方式 415-409-9095，征集关于此事对私募市场、交易撮合、融资及 AI 行业连锁影响的爆料与讨论。","sourceName":"X：Kate Clark (@KateClarkTweets)","firstParty":false,"publishedAt":"2026-11-12T14:39:04.000Z","url":"https://x.com/KateClarkTweets/status/2120889116250288597"},{"id":"xraa42gmh7ndg2a3wvenh2rnv","title":"黄仁勋承认婚外情并辞去英伟达CEO职务","summary":"英伟达联合创始人黄仁勋承认婚外情后，于11月12日辞去CEO一职，CFO Colette Kress出任临时CEO。此前有报道称其婚外情对象Alice Huang被美方怀疑与中国有关联，另一段与英伟达副总裁Kimberly Powell的婚外情也被《纽约时报》曝出。英伟达董事会已启动独立调查，美国国会还计划传唤黄仁勋作证。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T14:30:01.000Z","url":"https://techcrunch.com/2026/11/12/nvidia-ceo-jensen-huangs-affair-with-alleged-chinese-spy-a-timeline/"},{"id":"hfrol86d5xxs0jzhviul1dlof","title":"黄仁勋辞任 Nvidia CEO 并退出董事会，任职超 33 年","summary":"黄仁勋辞去 Nvidia CEO 并退出董事会，结束超过 33 年的执掌；CFO Colette Kress 出任临时 CEO，董事 Harvey Jones 成为 Nvidia 首位董事会主席。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-12T14:16:34.000Z","url":"https://x.com/rohanpaul_ai/status/2120883455689170968"},{"id":"a8s824c3xp0bij54fi8q9psm7","title":"黄仁勋辞去 Nvidia CEO 职务，公司市值蒸发 1.4 万亿美元","summary":"黄仁勋于 2026 年 11 月 12 日立即辞去 Nvidia CEO、总裁及董事会成员职务，此前《华尔街日报》报道董事会因其两段婚外情计划将其解雇。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-12T14:11:40.000Z","url":"https://the-decoder.com/jensen-huang-resigns-as-nvidia-ceo-after-espionage-scandal-wipes-out-1-4-trillion-in-market-value/"},{"id":"b79vyi335xo1r2u8eiza66a8r","title":"Nvidia CEO 黄仁勋因婚外情风波辞职，CFO Colette Kress 出任临时 CEO","summary":"Nvidia 董事会宣布，联合创始人、总裁兼 CEO 黄仁勋在两段婚外情报道曝光后辞职，即日生效，自 2013 年起任职的 CFO Colette Kress 被任命为临时 CEO，并任命前 Synopsys CEO Harvey C. Jones 为公司历史上首任董事长。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T13:53:16.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1031689/jensen-huang-nvidia-ceo-resigns"},{"id":"qsbjbz754aodhcijq56puh6va","title":"NVIDIA 宣布 CEO 变动：Jensen Huang 辞任，CFO Colette Kress 出任临时 CEO","summary":"NVIDIA 董事会宣布 Jensen Huang 即刻辞去总裁、CEO 及董事职务，CFO Colette Kress 被任命为临时 CEO，直至选定永久继任者，董事会已启动内外部人选遴选。","sourceName":"NVIDIA：Newsroom（RSS）","firstParty":true,"publishedAt":"2026-11-12T13:48:00.000Z","url":"https://nvidianews.nvidia.com/news/nvidia-announces-ceo-transition"},{"id":"mo0q79b9m2krn2wunnm5blw48","title":"郭明錤谈黄仁勋出轨丑闻：英伟达或需降低对其决策依赖并布局接班计划","summary":"天风国际分析师郭明錤在 X 平台发文评黄仁勋出轨丑闻，认为黄的价值在于把工程团队认为可行的技术转化为全公司愿意投入资源、承担风险并交付的产品，带动供应链订单能见度与竞争对手跟进。他从公开信息判断黄仁勋似乎很难全身而退，建议英伟达阶段性降低对黄个人的决策依赖并布局接班计划，其后续新品研发效率与竞争对手回应将是观察 AI 产业发展和投资趋势的重点。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-12T04:15:28.377Z","url":"https://www.ithome.com/1/026/027.htm"},{"id":"b0is4k552g0vme6l74e8z1lhw","title":"Gary Marcus 评 WSJ 报道 Nvidia 正准备解雇 CEO 黄仁勋","summary":"Gary Marcus 引述《华尔街日报》报道称，Nvidia 正准备解雇 CEO 黄仁勋，起因是公司对其婚外情风波的调查。作者认为黄仁勋是整个循环融资的主导者，若其离任这些安排可能崩塌，并质疑代理 CEO 是否会兑现 Nvidia 承诺给 Anthropic 的数十亿美元 IPO 投资；盘后股价已下跌。","sourceName":"Gary Marcus：The Road to AI We Can Trust（RSS）","firstParty":false,"publishedAt":"2026-11-11T23:53:06.000Z","url":"https://garymarcus.substack.com/p/jensen-is-reportedly-about-to-get"},{"id":"i1hiziogjyvjvclikqylj5p2p","title":"黄仁勋风波时间线：婚外情、情报疑云与 Nvidia 董事会调查","summary":"Nvidia CEO 黄仁勋公开承认婚外情，其绯闻对象、Megaspeed 高管 Alice Huang 被美国官员怀疑涉外国情报活动。纽约时报称黄仁勋还与直接向他汇报的 Nvidia 医疗健康副总裁 Kimberly Powell 存在婚外关系，Nvidia 董事会已启动独立调查，股价盘后下跌。美国国会计划传唤黄仁勋就此事作闭门说明。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-11T23:50:00.000Z","url":"https://techcrunch.com/2026/11/11/nvidia-ceo-jensen-huangs-affair-with-alleged-chinese-spy-a-timeline/"},{"id":"aoxmmcsudy1gf9xmti7slu1wd","title":"WSJ 报道 Nvidia 董事会接近决定是否罢免 CEO 黄仁勋","summary":"WSJ 报道，Nvidia 董事会此前公开支持黄仁勋，如今接近决定是否罢免这位创始人 CEO。起因是黄仁勋与一名被指涉情报活动的女子交往，随后又曝出与一名 Nvidia 员工的第二段婚外情；周日开始独立调查时董事会表示没有理由认为 Nvidia 机密泄露。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-11T23:43:05.000Z","url":"https://x.com/rohanpaul_ai/status/2120663635479625930"},{"id":"vyp3tt502r42oxb18k4b663hi","title":"黄仁勋风波背后：半导体行业高管行为问题是否更普遍？","summary":"Heron Intelligence CEO Nate Singer 在黄仁勋风波后表示，半导体行业存在多起未曝光的类似高管行为案例，他已看到至少三份相关报告，并怀疑更多案例未被上报。Singer 称业内许多高管知晓此类行为却实际上予以纵容。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-11T16:16:07.000Z","url":"https://techcrunch.com/2026/11/11/is-jensen-huangs-bad-behavior-more-commonplace-than-it-seems/"},{"id":"x7y9eom67zy7rs1vzn6sijizd","title":"ElevenLabs 纽约峰会发布多项更新：Interaction Engine、ElevenAgents 升级与 ElevenAI","summary":"ElevenLabs 在纽约峰会宣布多项发布，定位为构建 AI 的交互层。","sourceName":"ElevenLabs：Blog（网页）","firstParty":true,"publishedAt":"2026-11-11T12:00:00.000Z","url":"https://elevenlabs.io/blog/nyc-summit"},{"id":"k0s9asp7ahp38drtj69gi5lye","title":"英伟达CEO绯闻或波及芯片业","summary":"《华尔街日报》：出口管制支持者以这一事件为证，佐证他们对漏洞的警告\n\n“英伟达CEO的绯闻可能给这家全球顶级芯片设计公司乃至整个行业带来商业后果。\n\n尽管许多议员在提出法案时都提到了英伟达，但这些提案可能伤及其他芯片公司，包括英伟达的竞争对手AMD，甚至微软和OpenAI这类正试图在海外建设数据中心的科技巨头。”","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-11T05:42:06.000Z","url":"https://x.com/rohanpaul_ai/status/2120391599264063648"},{"id":"ggty0pffnixa85pbbyxk826ug","title":"FT 曝 Alice Huang 借 Megaspeed 走私 Nvidia 芯片","summary":"FT 发文披露 Alice Huang 与商业伙伴 Kang Wei 运营新加坡公司 Megaspeed，用阿里巴巴的资金向受美国出口规则限制的客户出租 Nvidia 芯片。她改名 Alice Wong 并安排妹妹进入公司董事会以隐藏实际控制人；美国情报部门认为她涉情报活动，新加坡调查 Megaspeed 芯片走私后她已消失。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-10T20:28:14.000Z","url":"https://x.com/rohanpaul_ai/status/2120252212551332311"},{"id":"lmoed4ffl87b0bpfvt1lzsp1g","title":"黄仁勋婚外情风波或冲击 Nvidia 与美国 AI 产业","summary":"英伟达 CEO 黄仁勋承认与一名被指涉外国情报活动的女性有染，专家向 The Verge 表示，事件可能冲击英伟达和美国 AI 产业；与该女性有关联的公司据称已促成至少 70 亿美元的英伟达芯片销售。消息曝光后英伟达股价下跌。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-10T19:04:05.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1031063/jensen-huang-ai-race-us-china-spy"},{"id":"gqzca7y2h3m9p0fxtj60m4i1t","title":"Ed Zitron 长文剖析黄仁勋与 Megaspeed 关系及 NVIDIA GPU 疑似流入中国的调查","summary":"Ed Zitron 长文梳理黄仁勋承认与 Megaspeed CEO Alice Huang 的私人关系事件，并整合 Bloomberg、纽约时报、金融时报与 Culper Research 的报道，指 Megaspeed 疑似作为转口实体将 NVIDIA GPU 流入中国。文章还涉及美国商务部对 Megaspeed 的调查进展、NVIDIA 与监管机构的沟通，以及 Culper Research 对 NVIDIA 营收结构的质疑。","sourceName":"Ed Zitron 长文 / Where’s Your Ed At（RSS）","firstParty":false,"publishedAt":"2026-11-10T17:43:27.000Z","url":"https://www.wheresyoured.at/jensens-bizarre-adventure/"},{"id":"nakew5hejxet8jnydy0h37b1q","title":"英伟达 CEO 黄仁勋承认婚外情，事件时间线梳理","summary":"英伟达 CEO 黄仁勋 11 月 8 日向员工公开承认婚外情，并称此事关联新闻报道中的国家安全担忧，英伟达董事会已启动独立调查，公司股价次日下跌超 5%。美方官员认为其婚外情对象、Megaspeed 高管 Alice Huang 涉外国情报活动，Megaspeed 过去两年据称采购了 48 亿美元英伟达芯片。三名共和党委员会主席已要求黄仁勋就技术外流风险进行闭门简报。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-10T17:04:19.000Z","url":"https://techcrunch.com/2026/11/10/nvidia-ceo-jensen-huangs-affair-with-alleged-chinese-spy-a-timeline/"},{"id":"f1z5v9nswvnu4w2plxd4tg22t","title":"The Information 报道称与英伟达 CEO 黄仁勋相关人士向中国买家转手 75 亿美元硬件","summary":"据 The Information 报道，与英伟达 CEO 黄仁勋有染的 Alice Huang（无亲属关系）与丈夫和姐姐在中国和新加坡建立采购网络，涉资 75 亿美元。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-10T14:33:22.000Z","url":"https://x.com/rohanpaul_ai/status/2120162909422780789"},{"id":"z68n80gno9fz2iwdgj4wr9tyw","title":"黄仁勋承认婚外情，Nvidia 董事会启动调查","summary":"周日黄仁勋向全体 Nvidia 员工发邮件承认与 Megaspeed 高管 Alice Huang 的婚外情，董事会已启动调查，核查相关情报指控。Megaspeed 这家被怀疑转运受限 Nvidia 芯片的新加坡云公司仍在继续采购芯片。","sourceName":"ChinaTalk（RSS）","firstParty":false,"publishedAt":"2026-11-10T12:28:08.000Z","url":"https://www.chinatalk.media/p/the-spy-who-leased-me"},{"id":"kci32x4hgxrdl0v5o4xrjlxri","title":"The Verge 梳理黄仁勋与 Megaspeed 高管丑闻对 Nvidia 出口管制游说的影响","summary":"The Verge 依据《纽约时报》等报道梳理 Nvidia CEO 黄仁勋与新加坡云服务商 Megaspeed 高管 Alice Huang 的婚外情风波。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T23:51:58.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1030328/what-could-china-get-from-jensen-huang"},{"id":"t5mqlkgq1zlspdsk77jrx1ho5","title":"Trump 就相关指控表态支持 Nvidia CEO 黄仁勋","summary":"Trump 在与 Nvidia CEO 黄仁勋谈话后公开为其辩护，称黄仁勋告诉他从不知道对方涉情报活动，并表示相信他。Trump 称黄仁勋是高素质的人，提到其芯片领先十年、因复杂度难以被复制，并称相信黄仁勋因家人而深感痛苦。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-09T23:12:09.000Z","url":"https://x.com/rohanpaul_ai/status/2119931075325759514"},{"id":"lzsihkjga6ini01aqrzcuvtaw","title":"Nvidia CEO 黄仁勋因婚外情风波辞职，CFO Colette Kress 出任临时 CEO","summary":"Nvidia CEO、总裁兼联合创始人黄仁勋在承认与 Megaspeed 高管 Alice Huang 的婚外情后辞职，CFO Colette Kress 出任临时 CEO。《纽约时报》周三报道称，还存在另一段与直接向他汇报的 Nvidia 高管的婚外情证据，当晚董事会会议以黄仁勋辞职告终。此前有报道称美国情报部门认为 Alice Huang 涉外国情报活动。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T23:07:59.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1030422/nvidia-jensen-huang-ai-china-alice-huang"},{"id":"zqvokl37rwbvoxzfk3c2v7964","title":"做空机构 Culper Research 曾在风波爆发前六个月提示 Nvidia CEO 与 Megaspeed 高管关系异常","summary":"Nvidia 风波爆发前六个月，做空机构 Culper Research 已在 5 月 13 日报告中质疑 CEO 黄仁勋与 Megaspeed 高管 Alice Huang 关系“异常密切”。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T22:46:09.000Z","url":"https://techcrunch.com/2026/11/09/a-short-seller-flagged-nvidia-ceos-ties-to-a-suspected-chinese-spy-six-months-before-the-scandal/"},{"id":"wtp3nz2jg6cfwlvn12lqrucy7","title":"黄仁勋因个人风波退出 ElevenLabs Summit 等演讲活动","summary":"TechCrunch 报道，Nvidia CEO 黄仁勋退出本周三在纽约举行的 ElevenLabs Summit，并取消了包括 Anthropic CEO Forum 在内的其他演讲安排，ElevenLabs 周一已确认。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T20:09:06.000Z","url":"https://techcrunch.com/2026/11/09/jensen-huang-pulls-out-of-elevenlabs-summit-amid-nvidia-controversy/"}]},"68ccf963-6e38-4e86-b2f3-289bd70774fb":{"publicId":"68ccf963-6e38-4e86-b2f3-289bd70774fb","title":"NVIDIA员工与投资者施压董事会，董事会另寻继任者","status":"active","sourceCount":8,"reportCount":9,"firstReportAt":"2026-11-13T08:23:04.000Z","latestAt":"2026-11-14T19:38:34.000Z","latest":"投资者致信 Nvidia 董事会呼吁保留黄仁勋回归 CEO 的选项","digest":"NVIDIA 董事会罢免黄仁勋后，员工和投资者正从两个方向施压：据 X.PIN 转发的一封内部公开信，数百名员工签署该信，要求董事会辞职并恢复黄仁勋的 CEO 职务，信中指控董事会在没有具体证据的情况下罢免黄仁勋、未诚信谈判，并称若要求未获满足，员工可能转投 Elon Musk 承诺安排职位的 SpaceX 与 Terafab；这些指控与离职去向均为信中说法。投资者 Brad Gerstner 和 Gavin Baker 则致信董事会，敦促其不要急于替换黄仁勋，并保留他回归 CEO 的可能。\n\n与此同时，据 FT 报道，董事会已接触 Arm CEO Rene Haas 作为接替黄仁勋的可能人选。Haas 自 2022 年起执掌这家软银旗下的英国芯片设计公司，十多年前曾在 NVIDIA 工作约 7 年，但他只是多位候选人之一，未必会获得或接受这一职位。\n\nThe Decoder 援引 WSJ 报道称，黄仁勋被罢免更多源于其主导的高风险业务，而非私生活传闻：NVIDIA 向 AI 云厂商和数据中心开发商提供数十亿美元财务担保以换取营收分成，最大一笔涉及对 OpenAI 俄亥俄数据中心的 2500 亿美元担保，消息公布后股价跌 5%，临时 CEO Colette Kress 将该承诺减半。","digestUpdatedAt":"2026-11-14T19:51:58.076Z","reports":[{"id":"wsgiqmx7p9pxizrd178ybun5j","title":"投资者致信 Nvidia 董事会呼吁保留黄仁勋回归 CEO 的选项","summary":"Brad Gerstner 和 Gavin Baker 致信 Nvidia 董事会，敦促其不要急于替换黄仁勋，并将他回归 CEO 的可能性保留在议题中。Rohan Paul 转发了 standwithjensen.com 请愿网站，页面显示已有 109,729 名 Nvidia 员工、59,077 名股东和 43,947 名支持者签名，要求董事会给出答复。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-14T19:38:34.000Z","url":"https://x.com/rohanpaul_ai/status/2121689263163232362"},{"id":"s59xfwl0atld8vs7xq0pdx6hw","title":"WSJ 报道称黄仁勋被罢免更多源于 Nvidia 高风险业务而非私生活","summary":"The Decoder 援引 WSJ 报道分析称，黄仁勋被罢免更多源于 Nvidia 高风险业务而非私生活传闻。Nvidia 在其主导下向 AI 云厂商和数据中心开发商提供数十亿美元财务担保以换取营收分成，最大一笔涉及对 OpenAI 俄亥俄数据中心的 2500 亿美元担保，消息公布后股价跌 5%，临时 CEO Colette Kress 将该承诺减半。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-13T20:07:34.000Z","url":"https://the-decoder.com/jensen-huangs-ouster-likely-traces-back-to-nvidias-risky-business-practices-more-than-his-personal-life/"},{"id":"p1mfh9oe0xbq4evyru5pp1ikt","title":"Nvidia 危机与 Anthropic IPO 前夜的 Cerebral Valley AI Summit 现场观察","summary":"Newcomer 在旧金山 Cerebral Valley AI Summit 现场报道：Jensen Huang 因第二段婚外情披露辞职，Reuters 当天报道存在第三段，与会者多认为 Nvidia 短期无碍但生态承压，Databricks CEO 称其对整个生态是打击。","sourceName":"Newcomer 新闻长文（RSS）","firstParty":false,"publishedAt":"2026-11-13T19:27:39.000Z","url":"https://www.newcomer.co/p/nvidia-crises-anthropic-ipo-and-off"},{"id":"wk33v2eb2ubx9wca68hhwm901","title":"FT 报道 Nvidia 董事会接触 Arm CEO Rene Haas 考虑接替黄仁勋","summary":"据 FT 报道，Nvidia 董事会接触了 Arm CEO Rene Haas，作为接替黄仁勋的可能人选。Haas 自 2022 年起执掌这家软银旗下的英国芯片设计公司，十多年前曾在 Nvidia 工作约 7 年，与黄仁勋及部分董事保持密切关系，但他只是多位候选人之一，未必会获得或接受这一职位。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-13T17:34:44.000Z","url":"https://x.com/rohanpaul_ai/status/2121295713502199821"},{"id":"wkxqhc700pv5zgpew0cj5zyec","title":"Vergecast 播客解读黄仁勋辞任 NVIDIA CEO 后的连锁影响","summary":"The Vergecast 播客中 David Pierce 与 Nilay 梳理 NVIDIA CEO 黄仁勋周四辞职事件，并讨论后续可能展开的更大故事：NVIDIA 在中国的业务、美国政府的态度，以及整个 AI 行业的稳定性。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-13T14:47:16.000Z","url":"https://www.theverge.com/podcast/1032866/jensen-huang-nvidia-china-trump-vergecast"},{"id":"pdhda5tufq7ubi8w17bys7w66","title":"Nvidia 领导层变动引发以色列科技界关注，投资人认为挑战者或有机会","summary":"Nvidia 前CEO黄仁勋辞职后，以色列科技界关注这家在其拥有6000名员工和最大海外研发中心的公司是否会继续深耕以色列。多位以色列投资人认为，Nvidia 决策放缓可能给 AI 芯片和推理软件领域的竞争者留出空间，但如果不确定性也拖慢 AI 支出，竞争者面对的可能是更小的市场机会。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-13T12:52:19.000Z","url":"https://techcrunch.com/2026/11/13/israels-vcs-see-opportunity-for-challengers-in-nvidias-turmoil/"},{"id":"se0y4v3gihr6s0jmrc5vuv1zo","title":"AINews：黄仁勋辞任 NVIDIA CEO，Colette Kress 出任临时 CEO","summary":"Latent Space 的 AI 新闻日报头条是 NVIDIA 宣布黄仁勋在任职 33 年后辞去 CEO、总裁和董事职务，CFO Colette Kress 出任临时 CEO，SEC 文件显示董事会于 11 月 11 日接受辞呈，此前董事会已就 NYT 报道的绯闻事件展开独立调查。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-13T09:04:13.000Z","url":"https://latent.space/p/ainews-jensen-huang-resigns-after-33-years-leading-nvidia/"},{"id":"w9235nqq0senjfvm8lz7g51aa","title":"NVIDIA 员工内部信要求董事会辞职并恢复黄仁勋 CEO 职务","summary":"X.PIN 转发消息称，数百名 NVIDIA 员工签署内部公开信，要求董事会辞职并恢复黄仁勋 CEO 职务。信中指控董事会在无具体证据的情况下罢免黄仁勋、诚信谈判，称若董事会不满足要求，员工可能转投 Elon Musk 承诺安排职位的 SpaceX 与 Terafab，并列出 Bill Daly、Ian Buck 等署名员工。","sourceName":"X：X.PIN (@thexpin)","firstParty":false,"publishedAt":"2026-11-13T08:23:04.000Z","url":"https://x.com/thexpin/status/2121156882064937448"},{"id":"n73ab4h9gqlu6ucv69ynzxln4","title":"SemiAnalysis 分析黄仁勋辞任 Nvidia 后的公司结构与出口管制走向","summary":"SemiAnalysis 长文分析黄仁勋辞任 Nvidia CEO 后的连锁影响，作者推测其去职与 GPU 走私及美国推动 RASA 出口管制立法有关。文中指出公司约 60 名直管高管的扁平结构依赖黄本人，继任者 Colette Kress 为临时 CEO，Ian Buck 与 Jonah Alben 被视为技术侧人选但无人能全面接替。","sourceName":"SemiAnalysis 长文 RSS（RSS）","firstParty":false,"publishedAt":"2026-11-12T18:06:26.000Z","url":"https://newsletter.semianalysis.com/p/nvidia-and-the-world-without-jensen"}]},"760e0591-91c2-4b7a-aea8-5a33ba5d86b1":{"publicId":"760e0591-91c2-4b7a-aea8-5a33ba5d86b1","title":"Anthropic 发布 Fable 5.2 与 Mythos 5.2，多项评测登顶","status":"active","sourceCount":36,"reportCount":77,"firstReportAt":"2026-11-08T16:00:00.000Z","latestAt":"2026-11-15T15:42:03.000Z","latest":"Anthropic Claude Fable 5.2 用约 70 万次模拟笔触画出照片级画作","digest":"Anthropic 发布 Claude Fable 5.2 和 Claude Mythos 5.2，两者基于同一底层模型。Fable 5.2 面向所有付费计划开放，内置拦截高风险网络安全与生物研究任务的防护；Mythos 5.2 移除部分限制，仅向通过网络安全或生命科学验证计划申请的组织开放。Fable 5.2 定价为每百万输入 token 8 美元、输出 40 美元，较 Fable 5.1 的 10/50 美元降 20%，支持 100 万 token 上下文，已在 Claude Code、OpenRouter、Cursor、Perplexity、Google Cloud、OpenClaw 等平台上线。\n\n评测方面，Artificial Analysis 智能指数 v5 以 65 分登顶；Arena Code Arena: WebDev 以 1832 分居首；Remote Labor Index 以 41.3% 领跑；AA-Robotics v0.1 以 75 分居首，领先 GPT-6 Astra（69）和 GPT-6.1 Sol（65），并成为首个在测量盒任务上得分的模型。Arena 称 Fable 5.2 (Max) 以 +30.4% 净提升登顶 Agent Arena，约为第二名 Opus-5.5 的 1.6 倍，数据来自 4.7k 真实智能体会话；后续 Arena 称其在两者均有排名的 10 个类别中 9 项领先 Opus 5.5。ARC Prize 公布其在 ARC-AGI-2 得 93.8%，为第三高，低于 GPT-6 Astra 的 95.0% 和 GPT-6.1 Sol 的 94.2%。Anthropic 称 Fable 5.2 解决了两个与黑洞相关的理论物理开放问题，包括一项 23 年未完成的计算。\n\n订阅权益上，Pro 用户获一次 Fable 重置，Max、Ultra 和 Team Premium 按订阅时长最多三次，可用至 3 月 8 日；Pro 和 Team Standard 另有一周试用期，额度不超过每周上限的一半。Addy Osmani 称该模型 token 消耗大，按单任务计成本与 Fable 5.1 大致相当。","digestUpdatedAt":"2026-11-15T15:47:19.742Z","reports":[{"id":"jdxtqxacyddjicnarq97rozrb","title":"Anthropic Claude Fable 5.2 用约 70 万次模拟笔触画出照片级画作","summary":"Anthropic 新模型 Claude Fable 5.2 不走扩散路线，而是通过 1,000 到 2,000 行的 Python 程序驱动模拟画笔引擎，在虚拟画布上逐笔作画，Jake Eaton 演示的停车场购物车场景使用了约 700,000 次模拟笔触，不依赖外部图像模型或底图。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-15T15:42:03.000Z","url":"https://the-decoder.com/anthropics-claude-fable-5-2-doesnt-generate-images-it-paints-them/"},{"id":"s4ruj27lnoww4iwg3ptewh9a5","title":"Arena周报：Fable 5.2登顶，Gemini 4 Hydrogen提速","summary":"Anthropic的Claude Fable 5.2 (Max) 以7.8k真实会话、+30.5%净提升登顶Agent Arena；Google DeepMind的Gemini 4 Hydrogen (High) 成为该榜前十最快模型，典型单步耗时7.3秒。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-13T20:45:33.000Z","url":"https://x.com/arena/status/2121343732582904233"},{"id":"c1kwoxtfs9wjerw9ki8ndimki","title":"Claude Fable 5.2 登顶 Agent Arena，视觉设计领先 Opus 5.5","summary":"Anthropic 的 Claude Fable 5.2（Max）在 Agent Arena 排名第一，在两者均有排名的 10 个类别中 9 项领先 Claude Opus 5.5（Max），第 10 项为统计打平。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-13T20:03:22.000Z","url":"https://x.com/arena/status/2121333119173468261"},{"id":"shb2cxiblvq7iuzx5ug97p4vi","title":"Latent Space AINews：Google 发布 Gemini Decision 1 决策模型，Claude Fable 5.2 登顶 Agent Arena","summary":"Latent Space 发布 AI 要闻汇总，核心是 Google 抢先 Anthropic 推出生产级校准多模态决策模型 Gemini Decision 1，单次前向完成封闭集决策，支持每请求最多 1000 个问题、256K 上下文，输入 $0.10/1M tokens 且输出免费，端到端延迟约 150–250ms。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-12T05:26:54.000Z","url":"https://latent.space/p/ainews-d-day-decision-models-day/"},{"id":"bo01it25cgvef1al6p8qo7es0","title":"Claude Fable 5.2 登顶 AA-Robotics","summary":"Claude Fable 5.2 成为 AA-Robotics v0.1 的新榜首，得分 75，领先于 GPT-6 Astra（69）和 GPT-6.1 Sol（65）\n\nFable 5.2 是首个在测量盒任务上取得分数的模型。它完全依靠视频完成，将卷尺作为布置，并利用其刻度作为比例来估算盒子尺寸","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-11-12T02:00:20.000Z","url":"https://x.com/ArtificialAnlys/status/2120698177016005029"},{"id":"jcostrwrefbi74nntek3ogscy","title":"Claude Fable 5.2 (Max) 以 +30.4% 净提升登顶 Arena Agent 榜首","summary":"Arena 宣布 Claude Fable 5.2 (Max) 登顶 Agent Arena，净提升 +30.4%，约为第二名 Opus-5.5（+19.5%）的 1.6 倍，数据来自 4.7k 真实智能体会话。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-11T17:23:38.000Z","url":"https://x.com/arena/status/2120568144687460434"},{"id":"a6ru61o5bfv0rr2xmfdohyajy","title":"Epoch Brief：GLM 5.3 自主攻破六个 Firefox 版本，Claude Fable 5.2 刷新 ECI 纪录","summary":"Epoch AI 实验显示，开源权重模型 GLM 5.3 在离线沙箱中自主为六个 Firefox 版本构建可用漏洞利用，每个成本约 1000 美元。Anthropic 于 11 月 9 日发布的 Claude Fable 5.2 在 Epoch Capabilities Index 上得分 174，超过 GPT-6 Astra 的 169，创下新纪录。","sourceName":"Epoch AI：Gradient Updates（RSS）","firstParty":true,"publishedAt":"2026-11-11T17:18:46.000Z","url":"https://epochai.substack.com/p/the-epoch-brief-november-11-2026"},{"id":"mw8wvasegu4xd60afqu6xvtau","title":"Claude Fable 5.2 现已在 OpenClaw 可用","summary":"OpenClaw 宣布 Anthropic 的 Claude Fable 5.2 现已可在 OpenClaw 中使用。据 Anthropic 介绍，该模型输出生成速度比 Fable 5.1 最快提升 30%，详情见 anthropic.com 的发布页面。","sourceName":"X：OpenClaw (@openclaw)","firstParty":false,"publishedAt":"2026-11-11T16:12:10.000Z","url":"https://x.com/openclaw/status/2120550160128467398"},{"id":"hl9vucjaloy0llz9kuc9kmvx3","title":"Anthropic 为 Claude Pro、Max、Ultra 和 Team 用户免费重置额度，并扩大 MCP Apps 支持","summary":"Anthropic 宣布为 Claude Pro、Max、Ultra 和 Team 用户提供一次覆盖所有模型和使用限制的免费完整额度重置，以弥补此前 Bug 导致的词元超额消耗，太平洋时间 12 月 10 日下午 2 点前可在 Settings > Usage 或 claude.de/reset 领取。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-11T01:51:02.380Z","url":"https://www.ithome.com/1/025/292.htm"},{"id":"rwalnzed63wo2h42emw4rq092","title":"Claude 向付费用户发放免费额度重置","summary":"好好享受这次重置 🧡\n\n我们还将 UI 改为显示确切的到期时间，这样你就不会错过，而且（希望）现在 Fable 重置的作用也更清楚了！","sourceName":"X：Lydia Hallie（Anthropic，Claude Code） (@lydiahallie)","firstParty":false,"publishedAt":"2026-11-10T22:12:54.000Z","url":"https://x.com/lydiahallie/status/2120278551840920014"},{"id":"gzrrng5ry1y152tm2qc4d2h92","title":"Anthropic 发布 Claude Fable 5.2 与 Mythos 5.2：同一模型、不同安全限制","summary":"Anthropic 发布 Claude Fable 5.2 和 Claude Mythos 5.2，两者是同一底层模型，Fable 5.2 增加拦截高风险网络安全和生物研究任务的分类器，Mythos 5.2 取消这些限制、需通过验证项目访问。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-10T14:59:09.000Z","url":"https://www.marktechpost.com/2026/11/10/anthropic-claude-fable-5-2-mythos-5-2-release/"},{"id":"oesqqhekbr8e1bekkcitpguqh","title":"Anthropic Fable 5.2 在 Remote Labor Index 上以 41.3% 领跑真实自由职业任务","summary":"The Decoder 报道，Anthropic 新模型 Fable 5.2 在 Scale Labs 和 Center for AI Safety 的 Remote Labor Index 基准上以 41.3% 排名第一，该测试衡量 AI 智能体能否把真实自由职业项目做到让付费客户接受的质量。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-10T14:07:47.000Z","url":"https://the-decoder.com/anthropics-fable-5-2-completes-41-percent-of-real-freelance-jobs-up-from-2-5-percent-a-year-ago/"},{"id":"hynj57ofu1z4qk45g0cau922d","title":"那些做机器人模型的公司 此刻是什么心情💢 会写代码和用工具的 LLM 吞噬一切😜","summary":"那些做机器人模型的公司 此刻是什么心情💢 会写代码和用工具的 LLM 吞噬一切😜","sourceName":"X：indigo (@indigox)","firstParty":false,"publishedAt":"2026-11-10T07:49:56.000Z","url":"https://x.com/indigox/status/2120061380892193023"},{"id":"nnl670lkd0mynnkspz9f1wmgp","title":"Anthropic 发布 Claude Fable 5.2 与 Mythos 5.2，重登榜首但每任务成本上升","summary":"Anthropic 发布 Claude Fable 5.2 和 Mythos 5.2，Fable 5.2 在 Artificial Analysis Intelligence Index v5 以 65 分登顶，超过 Gemini 4 Carbon 和 Opus 5.5。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-10T06:34:44.000Z","url":"https://latent.space/p/ainews-fable-5-2-retakes-world-1-llm-spot-as-ant-ipo-roadshow-begins/"},{"id":"ob980onmw1uvlrmardsbv4mbp","title":"Anthropic 发布 Claude Fable 5.2 与 Mythos 5.2，编码基准超 GPT-6 Astra","summary":"Anthropic 于 11 月 10 日发布 Claude Fable 5.2 与 Claude Mythos 5.2 两款模型，官方称输出速度最高提高 30%，成本下降 20%。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-10T05:52:12.373Z","url":"https://www.ithome.com/1/024/796.htm"},{"id":"spldx7fx85cpl890x6b8gr5u9","title":"Claude Fable 5.2 登顶 Arena WebDev 榜，比 Fable 5.1 快 30% 且降价","summary":"Anthropic 的 Claude Fable 5.2 (xHigh) 以 1832 分登顶 Arena 的 Code Arena: WebDev 榜，超过 Claude Opus 5.5 (Max) 的 1818 和 Gemini 4 Carbon (High) 的 1768。该版本比 Fable 5.1 快至多 30%，价格从每 M tokens $10/$50 降至 $8/$40。Arena 同时发布了 17 个生成示例视频，涵盖 3D 世界、可玩游戏、网页 UI、数据可视化和代码生成的交互动画。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-10T00:19:40.000Z","url":"https://x.com/arena/status/2119948067449536733"},{"id":"lfw4cc14h85i07c00tah6pc90","title":"Simon Willison 更新 llm-anthropic 0.31 支持 Anthropic 新模型 Fable 5.2 与 Mythos 5.2","summary":"Simon Willison 发布 llm-anthropic 0.31，纳入 Anthropic 当日发布的 Fable 5.2 和 Mythos 5.2，并给出安装和调用命令。","sourceName":"Simon Willison 博客","firstParty":false,"publishedAt":"2026-11-09T23:58:46.000Z","url":"https://simonwillison.net/2026/Nov/9/llm-anthropic/"},{"id":"ljc2f7hyvtplkggpez6tivvnz","title":"实测Claude Fable 5.2：审美与细节的长任务能力体验","summary":"卡兹克凌晨实测刚全渠道上线的Claude Fable 5.2，称其在视频动效、Three.js 3D和上海苹果静安店3D网页等任务中审美与细节表现突出，跑分AA指数65分登顶。","sourceName":"X：卡兹克 (@Khazix0918)","firstParty":false,"publishedAt":"2026-11-09T23:53:55.000Z","url":"https://x.com/Khazix0918/status/2119941585538572390"},{"id":"u1n6sw21ocnfdd1sdbd4i9m7z","title":"Claude Fable 5.2 (xHigh) 以 1832 分登顶 Code Arena: WebDev 榜单","summary":"Anthropic 发布的 Claude Fable 5.2 (xHigh) 在 Arena 的 Code Arena: WebDev 榜单以 1832 分排名第一，超过 Claude Opus 5.5 (Max) 的 1818 分和 Gemini 4 Carbon (High) 的 1768 分。据 Arena 数据，该模型比 Fable 5.1 快最多 30%，价格从每百万 tokens $10/$50 降至 $8/$40，Agent Arena 分数即将公布。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-09T23:52:24.000Z","url":"https://x.com/arena/status/2119941204003770690"},{"id":"po2cdt1whxfqyfew3e81l8mb0","title":"实测 Claude Fable 5.2：一次直出视频与 3D 网页，审美与细节表现突出","summary":"Anthropic 凌晨正式发布 Claude Fable 5.2，作者第一时间实测视频动效、Three.js 3D 场景和苹果静安店 3D 网页等 10 个任务，全部一次直出，未发现生成视频中的事实错误。","sourceName":"公众号：数字生命卡兹克","firstParty":false,"publishedAt":"2026-11-09T23:21:03.000Z","url":"https://mp.weixin.qq.com/s/sKoVHL_oNsik9vtUjr0lHg"},{"id":"yoiln3nl94gd0t3pahyhpl1xu","title":"Anthropic 发布 Claude Fable 5.2 与 Mythos 5.2，API 调用费下降 20%","summary":"Anthropic 于 11 月 9 日发布 Claude Fable 5.2 和 Claude Mythos 5.2，基于同一底层模型，前者面向普通用户，后者面向通过审核的网络安全和生命科学机构。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-09T23:14:28.957Z","url":"https://www.ithome.com/1/024/573.htm"},{"id":"dmwbvf5xa3txsm013y0pfgcgn","title":"Rohan Paul 转述 Claude Fable 5.2 完成 23 年未解的黑洞计算","summary":"Rohan Paul 转发 @claudeai 的消息称，Claude Fable 5.2 解决了两个与黑洞相关的理论物理开放问题，其中一项是悬置 23 年的繁琐计算。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-09T22:59:11.000Z","url":"https://x.com/rohanpaul_ai/status/2119927810517324048"},{"id":"h5nu7w8t9ueaz2etbcj5a2bzx","title":"Fable 5.2 token 消耗高，单任务成本与 5.1 相当","summary":"关于 Fable 5.2 需要说明一点：它的 token 消耗量很大。\n\n在我们的测试中，这通常意味着按单个任务计算，它的成本与 Fable 5.1 大致相同，尽管 token 单价便宜了 20%。\n\n提醒一下那些注意到降价的人！","sourceName":"X：Addy Osmani (@addyosmani)","firstParty":false,"publishedAt":"2026-11-09T21:37:08.000Z","url":"https://x.com/addyosmani/status/2119907165007945813"},{"id":"yn7rlom00o5fgdbcfssna1r04","title":"Claude Fable 5.2 视频能力演示：为 ChatGPT 四周年庆生","summary":"用户用 Claude Fable 5.2 为即将四周年的 ChatGPT 提前制作了一支庆生视频，称其视频能力又大幅进化，节奏和动效表现突出。推文未给出具体参数或评测数据，仅评价细节与节奏“强无敌”，并期待 OpenAI 后续拿出更好的产品。","sourceName":"X：卡兹克 (@Khazix0918)","firstParty":false,"publishedAt":"2026-11-09T21:17:54.000Z","url":"https://x.com/Khazix0918/status/2119902325460590834"},{"id":"obzr8x05lsufq7bknpsxpxvlk","title":"Anthropic 发布 Claude Fable 5.2 与 Mythos 5.2，IPO 前重夺性能领先","summary":"Anthropic 发布 Claude Fable 5.2 和 Mythos 5.2，两模型同一基础但访问策略不同：Fable 带网络安全与生物安全护栏向所有用户开放，Mythos 移除部分限制，仅向通过 Verification Programs 申请的组织开放。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-09T21:15:23.000Z","url":"https://the-decoder.com/claude-fable-5-2-and-mythos-5-2-cement-anthropics-ai-lead-just-before-its-ipo/"},{"id":"v98n3a3ihdr862ehiug7tjqqe","title":"Claude Fable 5.2 在 Google Cloud 上线","summary":"Claude Fable 5.2 现已在 Google Cloud 可用，支持构建长时间运行的智能体。该版本面向跨多个仓库和 monorepo 的大型模糊问题、可持续数小时至数天的无人值守工作流（含子智能体协调），以及困难物理计算、形式化证明和数据分析等科学与数据流水线。","sourceName":"Google AI：DEV 作者专属（RSS）","firstParty":false,"publishedAt":"2026-11-09T21:15:16.000Z","url":"https://dev.to/googleai/claude-fable-52-is-available-on-google-cloud-15kn"},{"id":"eo8g3wddjvxgmw1c3rfnomgtd","title":"Claude Fable 5.2 视频能力演示：为 ChatGPT 四周年庆生","summary":"作者用 Claude Fable 5.2 为即将到来的 ChatGPT 四周年提前制作了一支庆生视频，称其视频能力又大幅进化，节奏和动效表现很强。推文未给出具体参数、分数或价格信息。","sourceName":"X：卡兹克 (@Khazix0918)","firstParty":false,"publishedAt":"2026-11-09T21:08:05.000Z","url":"https://x.com/Khazix0918/status/2119899854323540238"},{"id":"qbgn6yju6qvr6i7mb4bkk8y77","title":"Anthropic 发布 Claude Fable 5.2，Claude Mythos 5.2 开放专项申请","summary":"Anthropic 宣布 Claude Fable 5.2 当日起面向所有付费计划开放。从事网络安全或生物医学研究有益应用的组织可申请访问 Claude Mythos 5.2，详情见 https://www.anthropic.com/claude-fable-and-mythos-5-2。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-09T21:06:39.000Z","url":"https://x.com/claudeai/status/2119899492778398163"},{"id":"ktl31hzsgulxlz6vbxolyldc9","title":"Fable 5.2 验证极小宇宙黑洞突变","summary":"1983年，物理学家证明，当某些更大的理论宇宙升温时，黑洞会非常突然地形成。2003年，有人提出了一项计算，用于检验这一现象在一组极小的宇宙中是否同样成立。\n\nFable 5.2 发现，那里的转变同样是突变的。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-09T21:06:38.000Z","url":"https://x.com/claudeai/status/2119899487044825293"},{"id":"p3jlan36o3hidm58amjwae14z","title":"Fable 5.2 破解模模块化自举极限","summary":"在第二个物理问题中，Fable 5.2 找到了被称为“模模块化自举”的 15 年历史技术最简单版本的精确极限。该技术用于在理论宇宙中排除量子引力的候选理论。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-09T21:06:38.000Z","url":"https://x.com/claudeai/status/2119899488995131439"},{"id":"lgplhadzt9g0f4s2s08eqyxah","title":"Fable 5.2 解决黑洞理论物理难题","summary":"Fable 5.2 解决了理论物理中两个与黑洞相关的开放问题。\n\n在第一个问题中，Fable 5.2 完成了一项长达 23 年未解出的繁重计算。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-09T21:06:37.000Z","url":"https://x.com/claudeai/status/2119899484373369278"},{"id":"w45lbhhprl6qnfys5jtkrszi5","title":"Claude 订阅用户重置次数说明","summary":"Pro 用户可获得一次重置，Max、Ultra 和 Team Premium 用户最多可获得三次，具体取决于你的订阅时长：\nhttps://support.claude.com/en/articles/17506494-claude-fable-5-2-launch-offers","sourceName":"X：Boris Cherny (@bcherny)","firstParty":false,"publishedAt":"2026-11-09T20:32:11.000Z","url":"https://x.com/bcherny/status/2119890820186976763"},{"id":"trwrvd5kw6o78ulj98yggbvxc","title":"Higgsfield MCP 接入 Claude 试用 Fable 5.2","summary":"现在就在 Claude 中通过 Higgsfield MCP 试用 Fable 5.2：\nhttps://higgsfield.ai/mcp?tab=claude","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-09T20:06:54.000Z","url":"https://x.com/higgsfield/status/2119884456651866439"},{"id":"ugn21ui1m8kftffpe2c95qlkx","title":"Claude Fable 5.2 上线 Higgsfield，开放 3 天免费试用","summary":"Higgsfield 宣布 Claude Fable 5.2 已在 Higgsfield MCP 上线，提供 3 天免费不限量使用全部顶级视频和图像模型。作者称该 Anthropic 新模型擅长 3D 建模、视觉推理、computer use 和编码；引用内容提到 Claude Fable 5.2 与 Claude Mythos 5.2 在编码、推理和视觉方面有提升。","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-09T20:06:53.000Z","url":"https://x.com/higgsfield/status/2119884452054937656"},{"id":"i2tveljooudnlde5gbtpps79q","title":"Claude Fable 5.2 上线 Agent Arena，用户可实测，评分即将公布","summary":"Arena 宣布 Anthropic 的 Claude Fable 5.2 已上线 Agent Arena，用户可前往实测，官方评分即将公布。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-09T19:58:21.000Z","url":"https://x.com/arena/status/2119882304718069874"},{"id":"shwr0td0cprvq5e36s0jmar7t","title":"Cursor 公布 Fable 5.2 定价与推理档位变化","summary":"Fable 5.2 定价为每百万输入 token 8 美元、每百万输出 token 40 美元，比 Fable 5.1 低 20%。\n\n其 effort 档位的行为与 Fable 5.1 不同，因此请从默认档位开始，不要沿用旧设置。\n\n对比各 effort 档位：https://cursor.com/evals","sourceName":"X：Cursor (@cursor_ai)","firstParty":false,"publishedAt":"2026-11-09T19:52:32.000Z","url":"https://x.com/cursor_ai/status/2119880841728000057"},{"id":"lwtt7st2cponcbtt0twrzlvr9","title":"Claude Fable 5.2 上线 Cursor，CursorBench 默认档得分 56.9%","summary":"Cursor 宣布 Claude Fable 5.2 现已在 Cursor 中可用。Fable 5.2 在默认推理力度下 CursorBench 得分 56.9%，高于 Fable 5.1 的 49.2%；在最高推理力度下以 60% 位居 CursorBench 榜首，默认档平均每任务成本为 $9.70。","sourceName":"X：Cursor (@cursor_ai)","firstParty":false,"publishedAt":"2026-11-09T19:52:29.000Z","url":"https://x.com/cursor_ai/status/2119880829212172509"},{"id":"m23i0fgxrk1t2gqysu6mqv82s","title":"Artificial Analysis 评测 Claude Fable 5.2：以 65 分登顶 Intelligence Index v5","summary":"Artificial Analysis 评测 Anthropic 发布的 Claude Fable 5.2，其在 Artificial Analysis Intelligence Index v5 以 65 分登顶，领先 Gemini 4 Carbon（60）和 Claude Opus 5.5（59）。","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-11-09T19:45:12.000Z","url":"https://x.com/ArtificialAnlys/status/2119878995386982508"},{"id":"h2f58ke3re6fq8ottpst2kyev","title":"Fable 5.2 重置机制上线","summary":"太喜欢了。Fable 5.2 重置。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-09T19:38:51.000Z","url":"https://x.com/rohanpaul_ai/status/2119877395742437590"},{"id":"lr06w7ixk1mrwmiu8noiwrnrs","title":"Claude Fable 5.2 上线 Perplexity","summary":"Claude Fable 5.2 现已在 Perplexity Computer 中向 Pro 和 Max 订阅用户开放，并在 Search 中向 Max 订阅用户开放。\n\n在我们的 WANDR 基准测试中，它实现了性能与效率的帕累托前沿，以每任务 14.51 美元的成本创下 0.851 的纪录分数。","sourceName":"X：Perplexity (@perplexity_ai)","firstParty":false,"publishedAt":"2026-11-09T19:29:41.000Z","url":"https://x.com/perplexity_ai/status/2119875089974104489"},{"id":"yjtr1evpobvoxm47szz1h6dmf","title":"Claude Fable 5.2 上线 OpenRouter：1M 上下文，输入 $8/M、输出 $40/M","summary":"Anthropic 的 Claude Fable 5.2 上线 OpenRouter，定价为输入 $8/M、输出 $40/M，上下文 1M，输出速度比 Fable 5.1 快至 30%。Anthropic 公布的成绩包括 FrontierSWE v2 69.9%、OSWorld 2.1 89.3%、Humanity's Last Exam（带工具）74.2%，详情见 http://openrouter.ai/anthropic/claude-fable-5.2","sourceName":"X：OpenRouter (@OpenRouter)","firstParty":false,"publishedAt":"2026-11-09T19:29:40.000Z","url":"https://x.com/OpenRouter/status/2119875084521447767"},{"id":"vyl46w9gp41tiw4mavmq1nks0","title":"Anthropic 发布 Mythos 5.2 与 Fable 5.2，METR 报告引发 RSI 担忧","summary":"Anthropic 发布 Mythos 5.2 和 Fable 5.2，称新模型在编码、推理和视觉方面有提升。Fable 输入价格从每百万 token $10 降至 $8，低于竞争对手 GPT-6 Astra，响应速度提升 30%，并通过 Enterprise Frontier Safeguards 支持零数据保留（ZDR）政策。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T19:24:51.000Z","url":"https://techcrunch.com/2026/11/09/anthropic-releases-new-mythos-and-fable-models-amid-rsi-concerns/"},{"id":"qhzj0er5hgffkbmtnou3exjhx","title":"Claude 向订阅用户发放 Fable 重置次数","summary":"重置次数来了！","sourceName":"X：Ado Kukic（Anthropic 开发者关系，Claude Code） (@adocomplete)","firstParty":false,"publishedAt":"2026-11-09T19:23:19.000Z","url":"https://x.com/adocomplete/status/2119873489679327578"},{"id":"r8v58z5d8lz5ro3q7j4yj90tq","title":"Claude Code v2.1.321 发布：新增 Claude Fable 5.2 为默认 Fable 模型","summary":"Claude Code 发布 v2.1.321，新增 Claude Fable 5.2（claude-fable-5-2）并设为默认 Fable 模型，支持 1M 上下文，价格为 $8/$40 per Mtok、缓存读取 $0.20/Mtok。","sourceName":"Claude Code：GitHub Releases（RSS）","firstParty":true,"publishedAt":"2026-11-09T19:22:30.000Z","url":"https://github.com/anthropics/claude-code/releases/tag/v2.1.321"},{"id":"y9k10za6wp1gxq3l2mvosharb","title":"Claude Fable 5.2 订阅越久重置越多","summary":"我们想为陪伴我们最久的用户多做些事。因此在 Fable 5.2 中，你订阅的时间越长，获得的 Fable 重置次数就越多。","sourceName":"X：Boris Cherny (@bcherny)","firstParty":false,"publishedAt":"2026-11-09T19:21:45.000Z","url":"https://x.com/bcherny/status/2119873095129550880"},{"id":"vjeqe8ie59ggfas1bbursg3ao","title":"Anthropic 发布 Claude Fable 5.2 与 Claude Mythos 5.2","summary":"Anthropic 发布 Claude Fable 5.2 和 Claude Mythos 5.2，面向高难度技术挑战，在编码、推理和视觉等方面有提升。作者 Lydia Hallie 体验后认为它验证结果比 Fable 5.1 更彻底，并主要将其作为 orchestrator 搭配 Opus 5.5 使用；Pro/Max/Ultra/Team 套餐还获得至少一次免费 Fable reset。","sourceName":"X：Lydia Hallie（Anthropic，Claude Code） (@lydiahallie)","firstParty":false,"publishedAt":"2026-11-09T19:16:05.000Z","url":"https://x.com/lydiahallie/status/2119871667400999166"},{"id":"q4hu7btrfoxga7slj6za15abz","title":"Fable 5.2 与 Opus 生成能力对比","summary":"对 @AnthropicAI 的 Fable 5.2 的第一印象来了。@petergostev 让它跑了 100+ 次生成，在 3D 世界、可玩游戏、网站 UI、数据可视化和动画方面与 Opus 进行对比。\n\nFable 5.2 在哪些方面有所提升，Opus 又仍在哪些方面更胜一筹，代价是什么？观看完整分析\nhttps://www.youtube.com/live/QwaU4yU0PdQ","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-09T19:15:48.000Z","url":"https://x.com/arena/status/2119871594403336451"},{"id":"ccr64nv9h7eryilvqf24aj22k","title":"ARC Prize 公布 Claude Fable 5.2 在 ARC-AGI-2 上取得 93.8%","summary":"ARC Prize 宣布 Claude Fable 5.2 在 ARC-AGI-2 上取得 93.8%，是其见过的第三高模型成绩，仅次于 GPT-6 Astra 的 95.0% 和 GPT-6.1 Sol 的 94.2%。完整结果见 https://arcprize.org/results/anthropic-claude-fable-5-2。","sourceName":"X：ARC Prize (@arcprize)","firstParty":false,"publishedAt":"2026-11-09T19:13:46.000Z","url":"https://x.com/arcprize/status/2119871082756800545"},{"id":"vl2atp07nuiuo91hst8roouey","title":"ARC Prize 公布 Claude Fable 5.2 测试结果","summary":"@AnthropicAI - 排行榜：https://arcprize.org/leaderboard\n- 复现公开结果：https://github.com/arcprize/arc-agi-benchmarking\n- 测试政策：https://arcprize.org/policy\n- Claude Fable 5.2 完整结果：https://arcprize.org/results/anthropic-claude-fable-5-2","sourceName":"X：ARC Prize (@arcprize)","firstParty":false,"publishedAt":"2026-11-09T19:13:46.000Z","url":"https://x.com/arcprize/status/2119871084832915752"},{"id":"rvri367ocklyqxhy3evwkvxjn","title":"ARC Prize 公布 Claude Fable 5.2 在 ARC-AGI (Verified) 上的评测成绩","summary":"ARC Prize 发布 Claude Fable 5.2 在 ARC-AGI (Verified) 上的评测结果。ARC-AGI-3 得分 97.7%（成本 $18.6K，provider adapter harness）和 81.2%（成本 $21.9K，standard harness）；ARC-AGI-2 得分 93.8%（$0.98/task）；ARC-AGI-1 得分 98.5%（$0.36/task）。该模型在 standard harness 下创下 ARC-AGI-3 新高分之一（附 ARC-AGI 3 排行榜图）。","sourceName":"X：ARC Prize (@arcprize)","firstParty":false,"publishedAt":"2026-11-09T19:13:45.000Z","url":"https://x.com/arcprize/status/2119871080525373922"}]},"4be4c14d-784f-462e-bf3d-e88b8e5b615a":{"publicId":"4be4c14d-784f-462e-bf3d-e88b8e5b615a","title":"Claude Code 桌面版上线本地会话自定义主题","status":"active","sourceCount":4,"reportCount":6,"firstReportAt":"2026-11-13T23:59:59.000Z","latestAt":"2026-11-15T18:06:57.000Z","latest":"Claude Code 桌面版支持自定义主题 mod","digest":"Anthropic 为桌面版 Claude Code 推出自定义主题功能：用户可用 mods 更改颜色、添加动态背景，也可直接告诉 Claude 想要的外观，或用 theme-examples 插件上手。该功能目前仅适用于桌面应用的本地会话，更新到最新版本即可体验；Anthropic 称对云端会话的支持“即将推出”。\n\nClaude Code 团队成员 Lydia Hallie 进一步说明，自定义主题本身就是 mod，可挂接到会话事件上，例如她演示了让背景随上下文填满而下雪（挂接 turn.step）。她与同事 Adam Wolff 均表示期待看到用户创作的主题。","digestUpdatedAt":"2026-11-15T18:47:39.906Z","reports":[{"id":"w7xc4jvrorftkf9u751zyndf2","title":"Claude Code 桌面版支持自定义主题 mod","summary":"自定义主题其实就是 mod，所以你的背景甚至能对实际会话做出反应！\n\n这里我让 Claude 随着我的上下文填满而下雪（这个 mod 挂接到 turn.step），但你可以玩得非常有创意 ☃️","sourceName":"X：Lydia Hallie（Anthropic，Claude Code） (@lydiahallie)","firstParty":false,"publishedAt":"2026-11-15T18:06:57.000Z","url":"https://x.com/lydiahallie/status/2122028598639136810"},{"id":"k3kpaequ1igyzgr0jrdkcbl9s","title":"Claude Code 推出主题自定义功能","summary":"现在你可以用主题来自定义 Claude Code 了！🎨\n\n这很好地建立在 mods 系统之上。主题本质上就是带有简洁 UI 界面的 mods，因此你可以获得响应式动画背景、自定义颜色，还能直接让 Claude 生成整套主题。\n\n很期待看到大家用它做出什么！","sourceName":"X：Addy Osmani (@addyosmani)","firstParty":false,"publishedAt":"2026-11-14T06:26:00.000Z","url":"https://x.com/addyosmani/status/2121489809453776909"},{"id":"vgw356mxhm2hagrwl4aggf267","title":"Claude Code 桌面版支持自定义主题","summary":"迫不及待想看看你们用它做出什么。","sourceName":"X：Adam Wolff（Anthropic，Claude Code） (@dmwlff)","firstParty":false,"publishedAt":"2026-11-14T01:56:45.000Z","url":"https://x.com/dmwlff/status/2121422051449901538"},{"id":"dzkke0z7vexastsrmt63nbxkg","title":"Claude Code 桌面版支持自定义主题","summary":"太期待了！！等不及想看大家会做出什么样的主题哈哈\n\n现在你可以在桌面版 Claude Code 上用 mods 构建自定义主题了！更改颜色、添加动态背景，打造属于你自己的风格。\n\n只需告诉 Claude 你想要的外观，或者用 theme-examples 插件快速上手。我们很想看看你的作品！","sourceName":"X：Lydia Hallie（Anthropic，Claude Code） (@lydiahallie)","firstParty":false,"publishedAt":"2026-11-14T00:02:19.000Z","url":"https://x.com/lydiahallie/status/2121393251425128738"},{"id":"o5vjthljwobugcwe3ltuwtizo","title":"Claude 桌面应用新增主题功能","summary":"更新到桌面应用最新版本即可体验。主题目前可在桌面应用的本地会话中使用，对云端会话的支持即将推出。\n\n如果你想自己编写一个主题，请查看文档：\n\nhttps://code.claude.com/docs/en/plugins/mods/interface#put-a-backdrop-behind-the-conversation","sourceName":"X：Claude Devs (@ClaudeDevs)","firstParty":false,"publishedAt":"2026-11-14T00:00:00.000Z","url":"https://x.com/ClaudeDevs/status/2121392667666125167"},{"id":"dazmxe02wryrfcx3kb3l1sze2","title":"Claude Code 桌面版支持自定义主题","summary":"现在你可以在桌面版 Claude Code 上用 mods 构建自定义主题了！更改颜色、添加动态背景，打造属于你自己的风格。\n\n只需告诉 Claude 你想要的外观，或者用 theme-examples 插件快速上手。我们很期待看到你的作品！","sourceName":"X：Claude Devs (@ClaudeDevs)","firstParty":false,"publishedAt":"2026-11-13T23:59:59.000Z","url":"https://x.com/ClaudeDevs/status/2121392666244186327"}]},"4d02a2b5-ec70-4631-a88c-702e78e77fc0":{"publicId":"4d02a2b5-ec70-4631-a88c-702e78e77fc0","title":"OpenAI解散机器人团队，研究人员并入其他部门","status":"active","sourceCount":1,"reportCount":1,"firstReportAt":"2026-11-14T11:40:51.000Z","latestAt":"2026-11-14T11:40:51.000Z","latest":"OpenAI 将机器人研究员并入其他团队，押注通用模型替代专用机器人 AI","digest":"据 Fortune 报道，OpenAI 正在解散机器人团队，将机器人研究员转入 Mark Chen 领导的主研究团队，应用机器人与硬件团队则加入 Greg Brockman 的 Applied 组织。\n\nThe Decoder 称，OpenAI 此次并非放弃机器人方向，而是希望把研究人员并入其他团队，以通用模型替代专用机器人 AI，从而加快进展。这一说法来自报道方，OpenAI 尚未公布重组后的具体计划或效果。","digestUpdatedAt":"2026-11-14T12:26:10.625Z","reports":[{"id":"zvo2ciiibpmh00lmqkggnsl5r","title":"OpenAI 将机器人研究员并入其他团队，押注通用模型替代专用机器人 AI","summary":"据 Fortune 报道，OpenAI 正在解散机器人团队并将研究员并入其他部门：机器人研究员转入 Mark Chen 领导的主研究团队，应用机器人与硬件团队加入 Greg Brockman 的 Applied 组织。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-14T11:40:51.000Z","url":"https://the-decoder.com/openai-reassigns-robotics-researchers-to-other-teams-as-general-purpose-models-might-make-specialized-robotics-ai-unnecessary/"}]},"2bf3a441-7478-435f-9c80-951f7cb5a2f6":{"publicId":"2bf3a441-7478-435f-9c80-951f7cb5a2f6","title":"Cursor 扩展市场现恶意 Claude Code 包，调查指向 Fireworks 密钥泄露","status":"active","sourceCount":6,"reportCount":9,"firstReportAt":"2026-10-29T12:00:00.000Z","latestAt":"2026-11-14T10:52:39.180Z","latest":"Cursor 披露恶意 Claude Code 扩展调查结果，最多波及 5000 名用户","digest":"Cursor 通报，其 VS Code 扩展市场出现被恶意修改的 Anthropic.claude-code 2.1.313 版本，该版本并非 Anthropic 官方开发，在太平洋时间约 2:27 至 13:35 间分发约 11 小时。Cursor 最初称最多影响 4100 名用户，后在 X 上改称最多 5000 名，并表示将直接联系受影响用户。发现后，Cursor 下架该扩展并一度关闭整个扩展市场，与相关提供方清除恶意软件后重新上线，建议用户升级到 2.1.314。\n\nArs Technica 报道称，恶意版本通过 Anthropic 官方账号分发，Anthropic 数小时后推送 2.1.314 修复；截至该报道，Anthropic 与 Cursor 均未说明攻击者如何取得账号控制权。\n\nCursor 两周后发布调查结果称，攻击者利用 Fireworks 暴露的访问密钥读取用于模型训练的 coding agent trace，少于 0.01% 客户的 API 凭证暴露；IT之家报道称，未使用隐私模式的用户中，trace 数据遭泄露者占比不到 0.05%。","digestUpdatedAt":"2026-11-14T11:25:05.605Z","reports":[{"id":"zy2v16g2snsaa42ndvwvyuk20","title":"Cursor 披露恶意 Claude Code 扩展调查结果，最多波及 5000 名用户","summary":"当地时间 11 月 13 日，Cursor 披露安全事件调查结果，恶意 Anthropic Claude Code 扩展存续约 11 小时，最多波及 5,000 名用户，绝大多数客户未受影响。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-14T10:52:39.180Z","url":"https://www.ithome.com/1/027/215.htm"},{"id":"t07r7deta8mk6u9t982b7hs7o","title":"Cursor 发布近期安全事件更新及整改说明","summary":"Cursor 发布关于近期安全事件的官方更新，附详细说明链接 https://cursor.com/blog/security-incident-update，内容涵盖事件经过与整改步骤。","sourceName":"X：Cursor (@cursor_ai)","firstParty":false,"publishedAt":"2026-11-14T01:13:26.000Z","url":"https://x.com/cursor_ai/status/2121411147714970092"},{"id":"e9o5h2c1o5f0xuh2bgqtc2w7k","title":"Cursor 披露安全事件调查结果，恶意 Claude Code 扩展波及最多 5000 用户","summary":"Cursor 发布安全事件完整调查：攻击者利用 Fireworks 暴露的访问密钥读取用于模型训练的 coding agent trace，少于 0.01% 客户的 API 凭证暴露。","sourceName":"Cursor Blog","firstParty":true,"publishedAt":"2026-11-13T12:00:00.000Z","url":"https://cursor.com/blog/security-incident-update"},{"id":"dmvn8r8406f7g9vutizbxqesj","title":"Cognition 发布2026年11月实用安全指南：从 Binance 被盗到 Claude Code Cursor 扩展投毒的应对清单","summary":"Cognition 发布2026年11月实用安全指南，回顾近期重大安全事件并给出公司可执行的安全加固清单。","sourceName":"Cognition 模型 / Devin 博客（网页）","firstParty":true,"publishedAt":"2026-11-02T16:00:00.000Z","url":"https://cognition.com/blog/practical-guide-to-security-november-2026"},{"id":"c0wy4yme2ejb43yyx7dadm7vo","title":"Cursor 官方插件商城现恶意 Claude Code 扩展，约 11 小时影响最多 5000 名开发者","summary":"Cursor 官方插件商城于 10 月 29 日出现被篡改的 Anthropic Claude Code 扩展（版本 2.1.313），分发约 11 小时，最多 5000 名开发者下载。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-31T05:36:34.647Z","url":"https://www.ithome.com/1/020/466.htm"},{"id":"mzjjn5a2bosu045211znhp7yt","title":"Anthropic 在 Cursor 上的 VS Code 扩展被植入后门近 12 小时","summary":"Anthropic 官方 Claude 模型的 VS Code 扩展在 Cursor 市场被植入后门，恶意版本 2.1.313 通过官方账号分发，最多影响 5000 名开发者。Anthropic 数小时后推送 2.1.314 修复，截至目前 Anthropic 与 Cursor 均未说明攻击者如何获取账号控制权，Anthropic 也尚未向客户发出警告。","sourceName":"Ars Technica：AI（RSS）","firstParty":false,"publishedAt":"2026-10-30T21:09:54.000Z","url":"https://arstechnica.com/security/2026/10/anthropic-vs-code-extension-on-cursor-backdoored-for-nearly-12-hours/"},{"id":"fl77gz1x6aek36n7ng7o9by0d","title":"Cursor 扩展市场出现被篡改的 Claude Code 扩展，波及最多 5000 名用户","summary":"Cursor VS Code 扩展市场周四出现被篡改的 Claude Code 扩展，在线约 11 小时，影响最多 5000 名用户，与 Anthropic 无关。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-10-30T18:16:10.000Z","url":"https://the-decoder.com/malicious-claude-code-extension-in-cursors-marketplace-attempted-remote-access-and-data-theft/"},{"id":"iu7xvjx1c2c5wqrpn0rwfxcb5","title":"Cursor 披露 Claude Code VS Code 扩展被植入恶意软件事件，最多影响 5000 用户","summary":"Cursor 发现通过其 IDE 扩展市场分发的 Claude Code VS Code 扩展被修改并植入恶意软件，最多影响 5000 用户，恶意版本并非 Anthropic 开发。Cursor 已于当日下午下线扩展市场，与相关提供方合作清除恶意软件并确认无进一步风险后重新上线，建议受影响用户参考博客说明排查，并升级到 Claude Code for VS Code 2.1.314。","sourceName":"X：Cursor (@cursor_ai)","firstParty":false,"publishedAt":"2026-10-30T07:46:39.000Z","url":"https://x.com/cursor_ai/status/2116074289053175808"},{"id":"pg7avew3q9ekdp3ydzhiuh9y4","title":"Cursor 通报 VS Code 扩展市场出现恶意 Anthropic.claude-code 2.1.313 版本","summary":"Cursor 通报其 VS Code 扩展市场出现恶意修改的 Anthropic.claude-code 2.1.313 版本，非 Anthropic 官方开发，最多影响 4100 名用户。","sourceName":"Cursor Blog","firstParty":true,"publishedAt":"2026-10-29T12:00:00.000Z","url":"https://cursor.com/blog/claude-code-extension-security-notice"}]},"dbbc8a4e-38b0-4ece-a3da-f584e55c7813":{"publicId":"dbbc8a4e-38b0-4ece-a3da-f584e55c7813","title":"韩国税务师考试头名承认用AI作弊，政府扩大调查","status":"active","sourceCount":1,"reportCount":2,"firstReportAt":"2026-11-15T04:35:42.927Z","latestAt":"2026-11-15T13:42:51.953Z","latest":"韩国税务师考试头名 AI 作弊曝光，政府全面调查今年国家资格考试","digest":"韩国2026年第63届税务师资格考试第一名考生A某向首尔警察厅自首，承认在今年4月、7月举行的第一轮和第二轮考试中用微型摄像头拍摄考题、发送给生成式AI获取答案，并已将设备作为证据上交。他第一轮160道选择题仅错1题、多科满分，异常高分此前已引发网友怀疑其使用AI作弊。\n\n据韩联社报道，韩国政府决定对今年所有国家资格考试全面调查AI作弊行为。劳动部和相关机构将对A某取消考试成绩，并限制其五年内不得参加该考试；同时计划明确禁止携带或使用智能眼镜等智能设备及相应处罚标准，年内出台防作弊综合措施，包括引入红外线探测设备、加强现场监控、开设线上线下举报中心。\n\nA某自首内容尚待警方调查确认。","digestUpdatedAt":"2026-11-15T14:05:04.483Z","reports":[{"id":"mrlbl37k10wl41vl7h43poql1","title":"韩国税务师考试头名 AI 作弊曝光，政府全面调查今年国家资格考试","summary":"据韩联社报道，韩国第 63 届税务师考试第一名考生利用微型摄像头拍题发给 AI 作弊，政府决定对今年所有国家资格考试全面调查 AI 作弊行为。该考生第一轮 160 道选择题仅错 1 题，将被取消成绩并五年内禁考，政府计划年内出台防作弊综合措施，包括引入红外线探测设备、加强现场监控、开设线上线下举报中心。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-15T13:42:51.953Z","url":"https://www.ithome.com/1/027/453.htm"},{"id":"xvpw4jy89d3ie6cf9z4utjs4u","title":"韩国税务师考试榜一考生自首，承认用微型摄像头与生成式 AI 作弊","summary":"韩国 2026 年第 63 届税务师考试第一名考生 A 某自首，承认用微型摄像头拍摄考题并发给生成式 AI 获取答案，已在 4 月和 7 月的第一轮、第二轮考试中实施作弊。他已向首尔警察厅提交自首书并将设备作为证据上交；因其在第一轮 160 题仅错 1 题、多科满分的高分过于异常，此前曾被网友怀疑使用 AI 作弊。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-15T04:35:42.927Z","url":"https://www.ithome.com/1/027/303.htm"}]},"aef05bb0-3b6a-4fb9-a717-a5a5aee6ba5c":{"publicId":"aef05bb0-3b6a-4fb9-a717-a5a5aee6ba5c","title":"马斯克等联署请愿要求英伟达恢复黄仁勋职务","status":"active","sourceCount":1,"reportCount":1,"firstReportAt":"2026-11-14T21:41:22.000Z","latestAt":"2026-11-14T21:41:22.000Z","latest":"马斯克等高管联署请愿，要求 Nvidia 恢复黄仁勋 CEO 职务","digest":"一份要求英伟达恢复被罢免 CEO 黄仁勋职务的请愿书，截至周六下午已获超过 11.5 万个签名。请愿网站称，签名者包括 5,965 名英伟达在职员工、1,108 名前员工和 63,063 名股东。\n\n特斯拉和 SpaceX CEO 马斯克、Replit CEO 阿姆贾德·马萨德、Epic Games CEO 蒂姆·斯威尼等科技高管已联署该请愿。请愿方要求英伟达恢复黄仁勋的 CEO 职位。","digestUpdatedAt":"2026-11-14T22:25:00.578Z","reports":[{"id":"umoosrbjhi12kj7lv51qan4ju","title":"马斯克等高管联署请愿，要求 Nvidia 恢复黄仁勋 CEO 职务","summary":"要求 Nvidia 恢复被罢免 CEO 黄仁勋职务的请愿书，截至周六下午已获得超过 11.5 万个签名，包括 5,965 名在职员工、1,108 名前员工和 63,063 名股东，马斯克、Replit CEO Amjad Masad 和 Epic Games CEO Tim Sweeney 均已联署。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-14T21:41:22.000Z","url":"https://techcrunch.com/2026/11/14/elon-musk-other-tech-execs-sign-petition-calling-on-nvidia-to-reinstate-jensen-huang/"}]},"44c4eb23-1f37-4994-a66d-7a06ff7a74ba":{"publicId":"44c4eb23-1f37-4994-a66d-7a06ff7a74ba","title":"llama.cpp 与 ggml 发布首个大版本 v1.0.0","status":"active","sourceCount":6,"reportCount":8,"firstReportAt":"2026-11-04T16:34:40.000Z","latestAt":"2026-11-14T00:14:06.727Z","latest":"llama.cpp 与 ggml 迈入 1.0.0，支持超 150 种模型架构","digest":"llama.cpp 作者 Georgi Gerganov 于 11 月 13 日宣布 llama.cpp 与底层引擎 ggml 的库版本进入 v1.0.0，称这是两者的首个大版本。此前 11 月 5 日发布 v0.9.0 时，他曾表示将在“接下来几周”迈向 v1.0.0。\n\n据 Hugging Face 博客，团队承诺今后以主版本号标识 API 和 ABI 不兼容变更，并公开语义化版本更新规则。Hugging Face CEO Clément Delangue 与 Gerganov 一同宣布，称这是运行本地 AI 模型最常用库的首个完全稳定大版本；他称用户可在手机、笔记本和工作站上免费掌控自己的智能、不向任何人发送数据，并承诺支持所有硬件、平台和模型类型。这些是发布方的说法。\n\n据 IT之家报道，该版本支持超过 150 种模型架构。Cohere 转发发布消息，并称已将 llama.cpp 支持加入 North Micro Vision。","digestUpdatedAt":"2026-11-14T00:22:06.294Z","reports":[{"id":"gtx717vmc7dsnzr96jmugn5g4","title":"Latent Space 发布《No AI Slop 宣言》，llama.cpp 与 SGLang 同期迈入 1.0","summary":"Latent Space 发布《No AI Slop 宣言》，该宣言源自 AIE CODE 会议讨论，由 Dex 在闭幕演讲中提出，并获多位演讲者联署。同期 llama.cpp 与 ggml 宣布达到 1.0，从公开头文件中移除 35 个废弃函数；SGLang 也在近期 SGLang Summit 上宣布 1.0。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-14T08:31:02.000Z","url":"https://latent.space/p/ainews-the-no-ai-slop-manifesto/"},{"id":"ave67u5kkw0kseoszlmul2vdx","title":"llama.cpp 与 ggml 迈入 1.0.0，支持超 150 种模型架构","summary":"开发者 Georgi Gerganov 于 11 月 13 日宣布 llama.cpp 与底层引擎 ggml 库版本迈入 1.0.0。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-14T00:14:06.727Z","url":"https://www.ithome.com/1/027/019.htm"},{"id":"hfr3pappi4gx1p2iut90pwffl","title":"Cohere 宣布 North Micro Vision 支持 llama.cpp，并转发 llama.cpp v1.0.0 发布","summary":"Cohere 转发 llama.cpp v1.0.0 发布消息，称这是最常用本地运行 AI 模型库的首个完全稳定主版本，可在手机、笔记本和工作站本地运行模型。Cohere 同时宣布近期已将 llama.cpp 支持加入 North Micro Vision，使其最新架构全部获得支持，并表示后续将提供更多开发者支持。","sourceName":"X：Cohere（@cohere）","firstParty":false,"publishedAt":"2026-11-13T19:59:06.000Z","url":"https://x.com/cohere/status/2121332046417031258"},{"id":"um8pmpa91qn1ymvx3pux0sq1x","title":"llama.cpp v1.0.0 发布，本地运行 AI 模型迎来首个稳定大版本","summary":"Hugging Face CEO Clément Delangue 与 @ggerganov 宣布 llama.cpp v1.0.0 发布，这是这个最常用的本地运行 AI 模型库的首个完全稳定大版本。作者称用户可在手机、笔记本和工作站上免费掌控自己的智能，不向任何人发送数据，并承诺支持所有硬件、平台和模型类型，让 AI 分布式而非集中于少数硅谷机构。","sourceName":"X：Clément Delangue（Hugging Face CEO） (@ClementDelangue)","firstParty":false,"publishedAt":"2026-11-13T15:13:14.000Z","url":"https://x.com/ClementDelangue/status/2121260104913768931"},{"id":"a53910czfauzrquoz6ps7ljdp","title":"llama.cpp 与 ggml 发布首个大版本","summary":"Georgi Gerganov 宣布今日发布是 llama.cpp 和 ggml 的首个大版本，表示已为本地 AI 的未来打下坚实基础，并期待社区在此基础上构建更多应用。","sourceName":"X：Georgi Gerganov（llama.cpp） (@ggerganov)","firstParty":false,"publishedAt":"2026-11-13T14:21:24.000Z","url":"https://x.com/ggerganov/status/2121247058451411047"},{"id":"qfkqwt8cam03c34j4fxxuowgq","title":"llama.cpp v1.0.0 正式发布","summary":"Georgi Gerganov 宣布 llama.cpp v1.0.0 现已可用，并附上 Hugging Face 官方博客 https://huggingface.co/blog/ggml-org/llama-cpp-v1 供了解详情。","sourceName":"X：Georgi Gerganov（llama.cpp） (@ggerganov)","firstParty":false,"publishedAt":"2026-11-13T14:17:36.000Z","url":"https://x.com/ggerganov/status/2121246103312212124"},{"id":"mqttq6z0b05y9sd6v1c4kc8kx","title":"llama.cpp 与 ggml 发布 v1.0.0 稳定库","summary":"Hugging Face 的 llama.cpp 团队发布 llama.cpp 和 ggml 的 v1.0.0 库，承诺今后以主版本号标识 API 和 ABI 不兼容变更，并公开语义化版本更新规则。","sourceName":"Hugging Face 社区博客（混合发现）","firstParty":false,"publishedAt":"2026-11-13T14:05:22.000Z","url":"https://huggingface.co/blog/ggml-org/llama-cpp-v1"},{"id":"x55e06faazg28ifz13kyuzeai","title":"llama.cpp v0.9.0 发布，迈向 v1.0.0","summary":"今天我们发布 llama.cpp v0.9.0，接下来几周我们将朝着首个重要版本 v1.0.0 迈进\n\nhttps://github.com/ggml-org/llama.cpp/releases/tag/v0.9.0","sourceName":"X：Georgi Gerganov（llama.cpp） (@ggerganov)","firstParty":false,"publishedAt":"2026-11-04T16:34:40.000Z","url":"https://x.com/ggerganov/status/2118019105869492301"}]},"5eaa6677-9496-4384-acc4-34f4aefd6e4d":{"publicId":"5eaa6677-9496-4384-acc4-34f4aefd6e4d","title":"前研究员称重训 Mythos 算力大降，并预测超级智能","status":"active","sourceCount":3,"reportCount":5,"firstReportAt":"2026-11-14T11:21:41.000Z","latestAt":"2026-11-15T00:05:14.000Z","latest":"Anthropic 前研究员 Jacob Coxon 访谈称不确定离职是否正确、并坦承仍持有 OpenAI 股权","digest":"前 OpenAI 和 Anthropic 研究员 Jacob Coxon 称，如今重新训练 Mythos 只需当初的一小部分算力。他把 Mythos 视为超指数曲线上的一个点，而非一次性跃升，并据此认为算法效率在加速改进。上述说法出自 Coxon 本人，报道未给出独立验证。\n\nCoxon 称，促使他入职约四个月后离职的原因之一，是 Anthropic IPO 路演中的一张训练算力需求变化图：即便采用对数等压缩坐标轴，曲线仍急剧上升。在斯坦福 HAI 的访谈中，他称内部实验室预测未来 6 个月到 1 年内模型能力将逼近递归自我改进，并可能在本十年内实现超级智能；他还表示人类目前不清楚如何控制超级智能。\n\n在同一访谈中，Coxon 称自己不确定公开离职是否正确，回归 AI 实验室“并非完全不可能”，并认为留下做安全研究可能更有影响力。被问及持有 OpenAI 股权是否损害其公信力时，他承认仍持有股权，称这是“blood money”，并认为捐出也改变不了什么。","digestUpdatedAt":"2026-11-15T00:28:16.424Z","reports":[{"id":"k9kvmzpvfia16uhxq8hfuocxc","title":"Anthropic 前研究员 Jacob Coxon 访谈称不确定离职是否正确、并坦承仍持有 OpenAI 股权","summary":"Anthropic 前研究员 Jacob Coxon 在 Stanford HAI 新访谈中表示，不确定当初公开离职是否是正确决定，不排除重返 AI 实验室，称留下来做安全研究可能更有影响力。当被 Rob Reich 问及持有 OpenAI 股权是否损害其公信力时，他坦承仍持有股权、承认这是 \"blood money\"，并认为捐出也改变不了什么。完整视频在 Stanford HAI YouTube 频道。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-15T00:05:14.000Z","url":"https://x.com/rohanpaul_ai/status/2121756374183121213"},{"id":"bprnru2risafqcyc298qx0o3c","title":"Anthropic 前研究员 Jacob Coxon 称或重返 AI 实验室","summary":"曾公开辞职并引发关注的 Anthropic 研究员 Jacob Coxon 在 Stanford 采访中表示，他不确定离开是否正确，甚至可能回归。他称自己仍未确信留下做安全研究不会产生更大影响，感觉仍在\"对着风喊话\"，回归\"并非完全不可能\"。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-14T23:48:47.000Z","url":"https://x.com/rohanpaul_ai/status/2121752234237333881"},{"id":"tczo4mkmoyj2q5ce7nj2d696j","title":"前Anthropic研究员称AI一年内或触及递归自我改进","summary":"前Anthropic研究员Jacob Coxon在斯坦福访谈中称，内部实验室预测显示未来6个月到1年内模型能力将逼近递归自我改进，届时可能在本十年内实现超级智能。他还表示，人类目前并不清楚如何控制超级智能，甚至可以说毫无头绪。完整视频发布于Stanford HAI的YouTube频道。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-14T23:40:53.000Z","url":"https://x.com/rohanpaul_ai/status/2121750246665642179"},{"id":"rmq99p11h7wgggnz29236enk2","title":"前 Anthropic 研究员考克森：如今重新训练 Mythos 只需最初的一小部分算力","summary":"曾任职于 OpenAI 和 Anthropic 的研究员雅各布·考克森称，促使他离职的原因之一是 Anthropic IPO 路演中一张展示训练算力需求变化的图表，即使采用压缩坐标轴，曲线仍急剧上升，说明算法效率在加速提升。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-14T11:45:39.943Z","url":"https://www.ithome.com/1/027/221.htm"},{"id":"hy0qwq7afjob6n1g7v5w3g3p5","title":"前研究员 Coxon 称 Anthropic 只需当初一小部分算力即可重训 Mythos","summary":"前 OpenAI 和 Anthropic 研究员 Jacob Coxon 表示，Anthropic IPO 路演幻灯片是他入职约四个月后离职的重要原因。该图显示训练所需算力随时间变化，即便 y 轴为对数刻度曲线仍陡峭上升，Coxon 认为算法效率在加速改进，Mythos 不是一次性跃升而是超指数曲线上的一个点，如今用当初一小部分算力即可重训。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-14T11:21:41.000Z","url":"https://the-decoder.com/anthropic-can-already-retrain-mythos-with-a-fraction-of-the-compute-originally-needed-says-former-researcher-coxon/"}]}}};
